export const GUIDED: Record<string, GuidedLab> = {"labex-matplotlib-matplotlib-sankey-diagram-creation":{"intro":"In this lab, we will learn how to use the Sankey class from the matplotlib.sankey module to create a long chain of connections using Python Matplotlib.","steps":[{"title":"Import necessary libraries and modules","body":["Import necessary libraries and modules","We begin by importing the necessary libraries and modules. We will be using matplotlib.pyplot and matplotlib.sankey."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.sankey import Sankey"}]},{"title":"Define the number of links per side","body":["Define the number of links per side","Next, we define the number of links per side in our chain. In this example, we will set it to 6."],"code":[{"lang":"python","text":"links_per_side = 6"}]},{"title":"Define the side function","body":["Now, we define the side function which generates a side chain."],"code":[{"lang":"python","text":"def side(sankey, n=1):\n    \"\"\"Generate a side chain.\"\"\"\n    prior = len(sankey.diagrams)\n    for i in range(0, 2*n, 2):\n        sankey.add(flows=[1, -1], orientations=[-1, -1],\n                   patchlabel=str(prior + i),\n                   prior=prior + i - 1, connect=(1, 0), alpha=0.5)\n        sankey.add(flows=[1, -1], orientations=[1, 1],\n                   patchlabel=str(prior + i + 1),\n                   prior=prior + i, connect=(1, 0), alpha=0.5)"}]},{"title":"Define the corner function","body":["Next, we define the corner function which generates a corner link."],"code":[{"lang":"python","text":"def corner(sankey):\n    \"\"\"Generate a corner link.\"\"\"\n    prior = len(sankey.diagrams)\n    sankey.add(flows=[1, -1], orientations=[0, 1],\n               patchlabel=str(prior), facecolor='k',\n               prior=prior - 1, connect=(1, 0), alpha=0.5)"}]},{"title":"Create the figure and axis objects","body":["Create the figure and axis objects","Now, we create the figure and axis objects using plt.subplots()."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"}]},{"title":"Create the Sankey object","body":["Next, we create the Sankey object using the ax object and set the unit to None."],"code":[{"lang":"python","text":"sankey = Sankey(ax=ax, unit=None)"}]},{"title":"Add the first diagram","body":["We add the first diagram using sankey.add() with flows=[1, -1] and orientations=[0, 1]."],"code":[{"lang":"python","text":"sankey.add(flows=[1, -1], orientations=[0, 1],\n           patchlabel=\"0\", facecolor='k',\n           rotation=45)"}]},{"title":"Add side chains and corner links","body":["Add side chains and corner links","Now, we add the side chains and corner links using the side() and corner() functions."],"code":[{"lang":"python","text":"side(sankey, n=links_per_side)\ncorner(sankey)\nside(sankey, n=links_per_side)\ncorner(sankey)\nside(sankey, n=links_per_side)\ncorner(sankey)\nside(sankey, n=links_per_side)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"sankey.finish()\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-a-sankey-diagram":{"intro":"In this tutorial, we will learn how to create a Sankey diagram using Python's Matplotlib library. Sankey diagrams are a type of flow diagram that are commonly used to visualize the flow of energy or materials through a system. They are especially useful for analyzing complex systems with multiple inputs and outputs.","steps":[{"title":"Import the Required Libraries","body":["We will start by importing the libraries required for creating Sankey diagrams using Matplotlib. We will import the Sankey class from the matplotlib.sankey module, and the pyplot module from Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.sankey import Sankey"}]},{"title":"Define the Data","body":["Next, we will define the data that we want to visualize using the Sankey diagram. In this example, we will use the data from Example 8.6 from Moran and Shapiro's \"Fundamentals of Engineering Thermodynamics\". The data represents the flow of energy through a Rankine power cycle. We will define the energy flows as a list of values."],"code":[{"lang":"python","text":"Hdot = [260.431, 35.078, 180.794, 221.115, 22.700,\n        142.361, 10.193, 10.210, 43.670, 44.312,\n        68.631, 10.758, 10.758, 0.017, 0.642,\n        232.121, 44.559, 100.613, 132.168]  # MW"}]},{"title":"Create the Figure and Axes","body":["We will create a figure object and add a single set of axes to it. We will also set the title of the plot."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(8, 9))\nax = fig.add_subplot(1, 1, 1, xticks=[], yticks=[],\n                     title=\"Rankine Power Cycle: Example 8.6 from Moran and \"\n                     \"Shapiro\\n\\x22Fundamentals of Engineering Thermodynamics \"\n                     \"\\x22, 6th ed., 2008\")"}]},{"title":"Create the Sankey Diagram","body":["We will create an instance of the Sankey class and pass in the axes object that we created in step 3. We will also set the format of the flow values and the unit of measurement. We will then add the flows to the diagram using the add method. We will specify the color of each flow using the facecolor parameter, and the labels for each flow using the labels parameter. We will also specify the path lengths for each flow using the pathlengths parameter and the orientation of each flow using the orientations parameter. Finally, we will connect the flows using the connect parameter."],"code":[{"lang":"python","text":"sankey = Sankey(ax=ax, format='%.3G', unit=' MW', gap=0.5, scale=1.0/Hdot[0])\nsankey.add(patchlabel='\\n\\nPump 1', rotation=90, facecolor='#37c959',\n           flows=[Hdot[13], Hdot[6], -Hdot[7]],\n           labels=['Shaft power', '', None],\n           pathlengths=[0.4, 0.883, 0.25],\n           orientations=[1, -1, 0])\nsankey.add(patchlabel='\\n\\nOpen\\nheater', facecolor='#37c959',\n           flows=[Hdot[11], Hdot[7], Hdot[4], -Hdot[8]],\n           labels=[None, '', None, None],\n           pathlengths=[0.25, 0.25, 1.93, 0.25],\n           orientations=[1, 0, -1, 0], prior=0, connect=(2, 1))\nsankey.add(patchlabel='\\n\\nPump 2', facecolor='#37c959',\n           flows=[Hdot[14], Hdot[8], -Hdot[9]],\n           labels=['Shaft power', '', None],\n           pathlengths=[0.4, 0.25, 0.25],\n           orientations=[1, 0, 0], prior=1, connect=(3, 1))\nsankey.add(patchlabel='Closed\\nheater', trunklength=2.914, fc='#37c959',\n           flows=[Hdot[9], Hdot[1], -Hdot[11], -Hdot[10]],\n           pathlengths=[0.25, 1.543, 0.25, 0.25],\n           labels=['', '', None, None],\n           orientations=[0, -1, 1, -1], prior=2, connect=(2, 0))\nsankey.add(patchlabel='Trap', facecolor='#37c959', trunklength=5.102,\n           flows=[Hdot[11], -Hdot[12]],\n           labels=['\\n', None],\n           pathlengths=[1.0, 1.01],\n           orientations=[1, 1], prior=3, connect=(2, 0))\nsankey.add(patchlabel='Steam\\ngenerator', facecolor='#ff5555',\n           flows=[Hdot[15], Hdot[10], Hdot[2], -Hdot[3], -Hdot[0]],\n           labels=['Heat rate', '', '', None, None],\n           pathlengths=0.25,\n           orientations=[1, 0, -1, -1, -1], prior=3, connect=(3, 1))\nsankey.add(patchlabel='\\n\\n\\nTurbine 1', facecolor='#37c959',\n           flows=[Hdot[0], -Hdot[16], -Hdot[1], -Hdot[2]],\n           labels=['', None, None, None],\n           pathlengths=[0.25, 0.153, 1.543, 0.25],\n           orientations=[0, 1, -1, -1], prior=5, connect=(4, 0))\nsankey.add(patchlabel='\\n\\n\\nReheat', facecolor='#37c959',\n           flows=[Hdot[2], -Hdot[2]],\n           labels=[None, None],\n           pathlengths=[0.725, 0.25],\n           orientations=[-1, 0], prior=6, connect=(3, 0))\nsankey.add(patchlabel='Turbine 2', trunklength=3.212, facecolor='#37c959',\n           flows=[Hdot[3], Hdot[16], -Hdot[5], -Hdot[4], -Hdot[17]],\n           labels=[None, 'Shaft power', None, '', 'Shaft power'],\n           pathlengths=[0.751,…"}]},{"title":"Add Labels and Formatting","body":["We will add labels to the patches in the Sankey diagram using the text attribute of each patch. We will also format the text to be bold and increase the font size."],"code":[{"lang":"python","text":"diagrams = sankey.finish()\nfor diagram in diagrams:\n    diagram.text.set_fontweight('bold')\n    diagram.text.set_fontsize('10')\n    for text in diagram.texts:\n        text.set_fontsize('10')"}]},{"title":"Show the Plot","body":["Finally, we will show the Sankey diagram using the show method of the pyplot module."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-formatting-tick-labels-with-matplotlib":{"intro":"This tutorial lab will guide you through the process of formatting tick labels using the Python Matplotlib library. It will cover the default tick formatter and various configurations possible via ~.axes.Axes.ticklabel_format.","steps":[{"title":"Import Required Libraries","body":[],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate Data for Example Plots","body":["Generate Data for Example Plots","We will generate data for three plots to demonstrate the different configurations possible with ~.axes.Axes.ticklabel_format."],"code":[{"lang":"python","text":"x = np.arange(0, 1, .01)\n\n# Plot 1\nplot1_x = x * 1e5 + 1e10\nplot1_y = x * 1e-10 + 1e-5\n\n# Plot 2\nplot2_x = x * 1e5\nplot2_y = x * 1e-4\n\n# Plot 3\nplot3_x = -x * 1e5 - 1e10\nplot3_y = -x * 1e-5 - 1e-10"}]},{"title":"Create Subplots for Example Plots","body":["Create Subplots for Example Plots","We will create a 3 x 3 grid of subplots to display our example plots."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(\n    3, 3, figsize=(9, 9), layout=\"constrained\", gridspec_kw={\"hspace\": 0.1})"}]},{"title":"Plot Data on Subplots","body":["We will plot our generated data on the subplots we created in Step 3."],"code":[{"lang":"python","text":"for col in axs.T:\n    col[0].plot(plot1_x, plot1_y)\n    col[1].plot(plot2_x, plot2_y)\n    col[2].plot(plot3_x, plot3_y)"}]},{"title":"Configure Tick Label Formatting","body":["Configure Tick Label Formatting","We will configure the tick label formatting for our subplots. The first subplot will use the default settings, the second subplot will use fancy formatting of mathematical expressions, and the third subplot will not use offset notation."],"code":[{"lang":"python","text":"# Subplot 1 (default settings)\naxs[0, 0].set_title(\"default settings\")\n\n# Subplot 2 (useMathText=True)\nfor ax in axs[:, 1]:\n    ax.ticklabel_format(useMathText=True)\naxs[0, 1].set_title(\"useMathText=True\")\n\n# Subplot 3 (useOffset=False)\nfor ax in axs[:, 2]:\n    ax.ticklabel_format(useOffset=False)\naxs[0, 2].set_title(\"useOffset=False\")"}]},{"title":"Display Example Plots","body":["We will display the example plots with the configured tick label formatting."],"code":[{"lang":"python","text":"plt.rcParams.update({\"axes.titleweight\": \"bold\", \"axes.titley\": 1.1})\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.rcParams.update({\"axes.titleweight\": \"bold\", \"axes.titley\": 1.1})\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-axis-transformation-techniques":{"intro":"Matplotlib is a Python library used for data visualization. It allows users to create a wide variety of charts, plots, and graphs. One of the key features of Matplotlib is its ability to apply scale transformations to axes. This allows for greater flexibility in presenting data, especially when dealing with very large or very small numbers. In this lab, we will learn how to apply various scale transformations to axes using Matplotlib.","steps":[{"title":"Import Libraries and Generate Data","body":["Import Libraries and Generate Data","First, we need to import the necessary libraries and generate some data to plot. In this example, we will use a normal distribution to generate data for the y-axis."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\n# make up some data in the interval ]0, 1[\ny = np.random.normal(loc=0.5, scale=0.4, size=1000)\ny = y[(y > 0) & (y < 1)]\ny.sort()\nx = np.arange(len(y))"}]},{"title":"Create a Linear Scale Plot","body":["The first type of scale transformation we will explore is linear. This is the default scale used in Matplotlib. To create a linear scale plot, we use the set_yscale() method and pass in the string 'linear'. We also add a title and grid to the plot."],"code":[{"lang":"python","text":"# linear\nplt.plot(x, y)\nplt.yscale('linear')\nplt.title('Linear Scale')\nplt.grid(True)"}]},{"title":"Create a Logarithmic Scale Plot","body":["Create a Logarithmic Scale Plot","The next type of scale transformation we will explore is logarithmic. To create a logarithmic scale plot, we use the set_yscale() method and pass in the string 'log'. We also add a title and grid to the plot."],"code":[{"lang":"python","text":"# log\nplt.plot(x, y)\nplt.yscale('log')\nplt.title('Logarithmic Scale')\nplt.grid(True)"}]},{"title":"Create a Symmetrical Logarithmic Scale Plot","body":["Create a Symmetrical Logarithmic Scale Plot","The third type of scale transformation we will explore is symmetrical logarithmic. This type of scale is useful when dealing with data that contains both positive and negative values. To create a symmetrical logarithmic scale plot, we use the set_yscale() method and pass in the string 'symlog'. We also set the linthresh parameter to 0.02 to specify the range of values around zero that will be linearly scaled. We also add a title and grid to the plot."],"code":[{"lang":"python","text":"# symmetric log\nplt.plot(x, y - y.mean())\nplt.yscale('symlog', linthresh=0.02)\nplt.title('Symmetrical Logarithmic Scale')\nplt.grid(True)"}]},{"title":"Create a Logit Scale Plot","body":["The fourth type of scale transformation we will explore is logit. This type of scale is useful when dealing with data that is bounded by 0 and 1. To create a logit scale plot, we use the set_yscale() method and pass in the string 'logit'. We also add a title and grid to the plot."],"code":[{"lang":"python","text":"# logit\nplt.plot(x, y)\nplt.yscale('logit')\nplt.title('Logit Scale')\nplt.grid(True)"}]},{"title":"Create a Custom Scale Plot","body":["The final type of scale transformation we will explore is custom. This allows us to define our own forward and inverse functions for the scale transformation. In this example, we will define a custom function to take the square root of the data. To create a custom scale plot, we use the set_yscale() method and pass in the string 'function'. We also define the forward() and inverse() functions and pass them as arguments to the functions parameter. We also add a title and grid to the plot."],"code":[{"lang":"python","text":"# Function x**(1/2)\ndef forward(x):\n    return x**(1/2)\n\ndef inverse(x):\n    return x**2\n\nplt.plot(x, y)\nplt.yscale('function', functions=(forward, inverse))\nplt.title('Custom Scale')\nplt.grid(True)"}]},{"title":"Create a Mercator Transform Scale Plot","body":["Create a Mercator Transform Scale Plot","As a bonus, we will also create a plot using the Mercator transform function. This is not a built-in function in Matplotlib, but we can define our own forward and inverse functions to create a Mercator transform scale plot. In this example, we will define the forward() and inverse() functions for the Mercator transform. We also add a title and grid to the plot."],"code":[{"lang":"python","text":"# Function Mercator transform\ndef forward(a):\n    a = np.deg2rad(a)\n    return np.rad2deg(np.log(np.abs(np.tan(a) + 1.0 / np.cos(a))))\n\ndef inverse(a):\n    a = np.deg2rad(a)\n    return np.rad2deg(np.arctan(np.sinh(a)))\n\nt = np.arange(0, 170.0, 0.1)\ns = t / 2.\n\nplt.plot(t, s, '-', lw=2)\nplt.yscale('function', functions=(forward, inverse))\nplt.title('Mercator Transform Scale')\nplt.grid(True)\nplt.xlim([0, 180])"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Function Mercator transform\ndef forward(a):\n    a = np.deg2rad(a)\n    return np.rad2deg(np.log(np.abs(np.tan(a) + 1.0 / np.cos(a))))\n\ndef inverse(a):\n    a = np.deg2rad(a)\n    return np.rad2deg(np.arctan(np.sinh(a)))\n\nt = np.arange(0, 170.0, 0.1)\ns = t / 2.\n\nplt.plot(t, s, '-', lw=2)\nplt.yscale('function', functions=(forward, inverse))\nplt.title('Mercator Transform Scale')\nplt.grid(True)\nplt.xlim([0, 180])"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-visualizing-variable-relationships":{"intro":"In this lab, we will learn how to create a simple scatter plot using Python's Matplotlib library. A scatter plot is a type of plot that displays values for two variables as a collection of points. Each point represents the values of the two variables, and the position of the point represents the values of the two variables. Scatter plots are useful for identifying relationships between variables and for identifying outliers.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","In this step, we will import the necessary libraries for creating a scatter plot. We will be using the Matplotlib library for creating the plot and the NumPy library for generating random data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate random data","body":["In this step, we will generate random data for our scatter plot. We will be generating 50 data points for each variable using the NumPy library."],"code":[{"lang":"python","text":"np.random.seed(19680801)\n\nN = 50\nx = np.random.rand(N)\ny = np.random.rand(N)"}]},{"title":"Define the size and color of the points","body":["Define the size and color of the points","In this step, we will define the size and color of the points in our scatter plot. We will be using the NumPy library to generate random values for the size and color of the points."],"code":[{"lang":"python","text":"colors = np.random.rand(N)\narea = (30 * np.random.rand(N))**2"}]},{"title":"Create the scatter plot","body":["In this step, we will create the scatter plot using the Matplotlib library. We will use the scatter function to create the plot and specify the size and color of the points."],"code":[{"lang":"python","text":"plt.scatter(x, y, s=area, c=colors, alpha=0.5)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.scatter(x, y, s=area, c=colors, alpha=0.5)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-customizable-scatter-plot-visualization":{"intro":"In this tutorial, we will learn how to create a scatter plot with varying marker colors and sizes using Python Matplotlib.","steps":[{"title":"Import necessary libraries","body":["We will start by importing the necessary libraries, which are Matplotlib and Numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Load data","body":["We will load a numpy record array from yahoo csv data with fields date, open, high, low, close, volume, adj_close from the mpl-data/sample_data directory. The record array stores the date as an np.datetime64 with a day unit ('D') in the date column."],"code":[{"lang":"python","text":"import matplotlib.cbook as cbook\n\nprice_data = cbook.get_sample_data('goog.npz')['price_data'].view(np.recarray)\nprice_data = price_data[-250:]  # get the most recent 250 trading days"}]},{"title":"Calculate values for scatter plot","body":["Calculate values for scatter plot","We will calculate delta1, volume, and close values for scatter plot."],"code":[{"lang":"python","text":"delta1 = np.diff(price_data.adj_close) / price_data.adj_close[:-1]\n\n# Marker size in units of points^2\nvolume = (15 * price_data.volume[:-2] / price_data.volume[0])**2\nclose = 0.003 * price_data.close[:-2] / 0.003 * price_data.open[:-2]"}]},{"title":"Create scatter plot","body":["We will create a scatter plot with varying marker colors and sizes using the calculated values."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.scatter(delta1[:-1], delta1[1:], c=close, s=volume, alpha=0.5)\n\nax.set_xlabel(r'$\\Delta_i$', fontsize=15)\nax.set_ylabel(r'$\\Delta_{i+1}$', fontsize=15)\nax.set_title('Volume and percent change')\n\nax.grid(True)\nfig.tight_layout()\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nax.scatter(delta1[:-1], delta1[1:], c=close, s=volume, alpha=0.5)\n\nax.set_xlabel(r'$\\Delta_i$', fontsize=15)\nax.set_ylabel(r'$\\Delta_{i+1}$', fontsize=15)\nax.set_title('Volume and percent change')\n\nax.grid(True)\nfig.tight_layout()\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-scatter-plot-with-histograms":{"intro":"This lab will guide you on how to create a scatter plot with histograms using Matplotlib. A scatter plot with histograms is a great way to visualize the distribution of two variables and their relationship. The scatter plot displays the relationship between the two variables, while the histograms show the distribution of each variable independently.","steps":[{"title":"Import libraries","body":["Before we can begin, we need to import the necessary libraries. In this lab, we will be using Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate random data","body":["We will generate some random data to use for the scatter plot and histograms."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\n# Generate random data\nx = np.random.randn(1000)\ny = np.random.randn(1000)"}]},{"title":"Define the scatter_hist function","body":["Define the scatter_hist function","We need to define the scatter_hist function, which takes in x and y data, as well as three axes, the main axes for the scatter plot, and two marginal axes. It will then create the scatter and histograms inside the provided axes."],"code":[{"lang":"python","text":"def scatter_hist(x, y, ax, ax_histx, ax_histy):\n    # Remove labels from the histograms\n    ax_histx.tick_params(axis=\"x\", labelbottom=False)\n    ax_histy.tick_params(axis=\"y\", labelleft=False)\n\n    # Create the scatter plot\n    ax.scatter(x, y)\n\n    # Determine nice limits by hand\n    binwidth = 0.25\n    xymax = max(np.max(np.abs(x)), np.max(np.abs(y)))\n    lim = (int(xymax/binwidth) + 1) * binwidth\n\n    bins = np.arange(-lim, lim + binwidth, binwidth)\n    ax_histx.hist(x, bins=bins)\n    ax_histy.hist(y, bins=bins, orientation='horizontal')"}]},{"title":"Define the axes positions using a gridspec","body":["Define the axes positions using a gridspec","We will now define a gridspec with unequal width- and height-ratios to achieve the desired layout. We will also create the axes and pass them to the scatter_hist function."],"code":[{"lang":"python","text":"# Start with a square Figure.\nfig = plt.figure(figsize=(6, 6))\n# Add a gridspec with two rows and two columns and a ratio of 1 to 4 between\n# the size of the marginal axes and the main axes in both directions.\n# Also adjust the subplot parameters for a square plot.\ngs = fig.add_gridspec(2, 2,  width_ratios=(4, 1), height_ratios=(1, 4),\n                      left=0.1, right=0.9, bottom=0.1, top=0.9,\n                      wspace=0.05, hspace=0.05)\n# Create the Axes.\nax = fig.add_subplot(gs[1, 0])\nax_histx = fig.add_subplot(gs[0, 0], sharex=ax)\nax_histy = fig.add_subplot(gs[1, 1], sharey=ax)\n# Draw the scatter plot and marginals.\nscatter_hist(x, y, ax, ax_histx, ax_histy)"}]},{"title":"Define the axes positions using inset_axes","body":["Define the axes positions using inset_axes","We can also use inset_axes to position the marginals _outside_ the main axes. The advantage of doing so is that the aspect ratio of the main axes can be fixed, and the marginals will always be drawn relative to the position of the axes."],"code":[{"lang":"python","text":"# Create a Figure, which doesn't have to be square.\nfig = plt.figure(layout='constrained')\n# Create the main axes, leaving 25% of the figure space at the top and on the right to position marginals.\nax = fig.add_gridspec(top=0.75, right=0.75).subplots()\n# The main axes' aspect can be fixed.\nax.set(aspect=1)\n# Create marginal axes, which have 25% of the size of the main axes.\n# Note that the inset axes are positioned *outside* (on the right and the top) of the main axes,\n# by specifying axes coordinates greater than 1.\n# Axes coordinates less than 0 would likewise specify positions on the left and the bottom of the main axes.\nax_histx = ax.inset_axes([0, 1.05, 1, 0.25], sharex=ax)\nax_histy = ax.inset_axes([1.05, 0, 0.25, 1], sharey=ax)\n# Draw the scatter plot and marginals.\nscatter_hist(x, y, ax, ax_histx, ax_histy)"}]},{"title":"Display the plot","body":["Finally, we can display the plot using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-scatter-hist-locatable-axes":{"intro":"In data visualization, scatter plots are used to show the relationship between two variables. Additionally, histograms are useful for showing the distribution of a single variable. In this tutorial, you will learn how to create a scatter plot with histograms using Python's Matplotlib library.","steps":[{"title":"Import Required Libraries","body":["In this step, we will import the necessary libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom mpl_toolkits.axes_grid1 import make_axes_locatable"}]},{"title":"Create Random Data","body":["In this step, we will create random data to use for the scatter plot."],"code":[{"lang":"python","text":"np.random.seed(19680801)\nx = np.random.randn(1000)\ny = np.random.randn(1000)"}]},{"title":"Create Scatter Plot","body":["In this step, we will create a scatter plot using the random data from Step 2."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(figsize=(5.5, 5.5))\nax.scatter(x, y)\nax.set_aspect(1.)"}]},{"title":"Create Histograms","body":["In this step, we will create histograms for the x and y variables using make_axes_locatable from mpl_toolkits.axes_grid1."],"code":[{"lang":"python","text":"divider = make_axes_locatable(ax)\nax_histx = divider.append_axes(\"top\", 1.2, pad=0.1, sharex=ax)\nax_histy = divider.append_axes(\"right\", 1.2, pad=0.1, sharey=ax)\n\nax_histx.xaxis.set_tick_params(labelbottom=False)\nax_histy.yaxis.set_tick_params(labelleft=False)\n\nbinwidth = 0.25\nxymax = max(np.max(np.abs(x)), np.max(np.abs(y)))\nlim = (int(xymax/binwidth) + 1)*binwidth\nbins = np.arange(-lim, lim + binwidth, binwidth)\n\nax_histx.hist(x, bins=bins)\nax_histy.hist(y, bins=bins, orientation='horizontal')\n\nax_histx.set_yticks([0, 50, 100])\nax_histy.set_xticks([0, 50, 100])"}]},{"title":"Display Plot","body":["In this step, we will display the scatter plot with histograms."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-scatter-plot-with-masked-data-using-matplotl":{"intro":"This tutorial will guide you through creating a scatter plot with masked data points using the Python Matplotlib library. We will also add a line to demarcate the masked regions.","steps":[{"title":"Importing the Required Libraries and Setting Random Seed","body":["Importing the Required Libraries and Setting Random Seed","We start by importing the necessary libraries and setting the random seed to ensure reproducibility."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Setting random seed for reproducibility\nnp.random.seed(19680801)"}]},{"title":"Generating Data for the Scatter Plot","body":["Generating Data for the Scatter Plot","Next, we generate data for the scatter plot. We create 100 data points with random x and y values between 0 and 0.9, and random radii between 0 and 10. The color of each data point is determined by the square root of its area."],"code":[{"lang":"python","text":"N = 100\nr0 = 0.6\nx = 0.9 * np.random.rand(N)\ny = 0.9 * np.random.rand(N)\narea = (20 * np.random.rand(N))**2  # 0 to 10 point radii\nc = np.sqrt(area)"}]},{"title":"Masking Data Points and Creating Scatter Plot","body":["Masking Data Points and Creating Scatter Plot","We mask the data points based on their distance from the origin. Data points with a distance less than r0 are masked in area1, and those with a distance greater than or equal to r0 are masked in area2. We then create a scatter plot of the masked data points with marker='^' and marker='o' for area1 and area2, respectively."],"code":[{"lang":"python","text":"r = np.sqrt(x ** 2 + y ** 2)\narea1 = np.ma.masked_where(r < r0, area)\narea2 = np.ma.masked_where(r >= r0, area)\nplt.scatter(x, y, s=area1, marker='^', c=c)\nplt.scatter(x, y, s=area2, marker='o', c=c)"}]},{"title":"Adding a Line to Demarcate Masked Regions","body":["Adding a Line to Demarcate Masked Regions","Finally, we add a line to demarcate the masked regions. We create an array of theta values and plot a circle with radius r0 using np.cos(theta) and np.sin(theta)."],"code":[{"lang":"python","text":"# Show the boundary between the regions:\ntheta = np.arange(0, np.pi / 2, 0.01)\nplt.plot(r0 * np.cos(theta), r0 * np.sin(theta))"}]},{"title":"Displaying the Scatter Plot","body":["We display the scatter plot using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-customizing-matplotlib-markers-for-data-visu":{"intro":"In this lab, we will explore different ways to specify markers using Python Matplotlib. Markers are used to denote points on a graph and can be customized in various ways to enhance data visualization.","steps":[{"title":"Import libraries and set random seed","body":["Import libraries and set random seed","We will start by importing the necessary libraries and setting a random seed to ensure reproducibility of results."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Set random seed\nnp.random.seed(19680801)"}]},{"title":"Generate random data","body":["We will generate random data using NumPy's random module."],"code":[{"lang":"python","text":"x = np.random.rand(10)\ny = np.random.rand(10)\nz = np.sqrt(x**2 + y**2)"}]},{"title":"Create subplots","body":["We will create a 2x3 grid of subplots using subplots() function."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(2, 3, sharex=True, sharey=True, layout=\"constrained\")"}]},{"title":"Customize markers","body":["We will customize markers in the following ways:","Method 1: Matplotlib marker symbol","We will use the marker parameter to specify a Matplotlib marker symbol.","We will use the marker parameter to specify a marker from TeX by enclosing a TeX symbol name in $-signs."],"code":[{"lang":"python","text":"axs[0, 0].scatter(x, y, s=80, c=z, marker=\">\")\naxs[0, 0].set_title(\"marker='>'\")"},{"lang":"python","text":"axs[0, 1].scatter(x, y, s=80, c=z, marker=r\"$\\clubsuit$\")\naxs[0, 1].set_title(r\"marker=r'\\$\\clubsuit\\$'\")"},{"lang":"python","text":"verts = [[-1, -1], [1, -1], [1, 1], [-1, -1]]\naxs[0, 2].scatter(x, y, s=80, c=z, marker=verts)\naxs[0, 2].set_title(\"marker=verts\")"}]},{"title":"Show the plot","body":["We will display the plot using show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-scatter-plots-with-legends":{"intro":"Scatter plots are used to visualize the relationship between two variables. A scatter plot with a legend is useful when there are multiple groups in the data, and we want to distinguish between them in the plot. In this lab, we will learn how to create scatter plots with legends in Python using Matplotlib library.","steps":[{"title":"Importing Required Libraries","body":["We begin by importing the necessary libraries, including NumPy and Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Creating a Scatter Plot with Multiple Groups","body":["Creating a Scatter Plot with Multiple Groups","We can create a scatter plot with multiple groups by looping through each group and creating a scatter plot for that group. We specify the color, size, and transparency of the markers for each group using the c, s, and alpha parameters, respectively. We also set the label parameter to the group name, which will be used in the legend."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nfor color in ['tab:blue', 'tab:orange', 'tab:green']:\n    n = 750\n    x, y = np.random.rand(2, n)\n    scale = 200.0 * np.random.rand(n)\n    ax.scatter(x, y, c=color, s=scale, label=color,\n               alpha=0.3, edgecolors='none')\n\nax.legend()\nax.grid(True)\n\nplt.show()"}]},{"title":"Automated Legend Creation","body":["We can also use the PathCollection.legend_elements method to automatically create a legend for a scatter plot. This method will try to determine a useful number of legend entries to be shown and return a tuple of handles and labels."],"code":[{"lang":"python","text":"N = 45\nx, y = np.random.rand(2, N)\nc = np.random.randint(1, 5, size=N)\ns = np.random.randint(10, 220, size=N)\n\nfig, ax = plt.subplots()\n\nscatter = ax.scatter(x, y, c=c, s=s)\n\n# produce a legend with the unique colors from the scatter\nlegend1 = ax.legend(*scatter.legend_elements(),\n                    loc=\"lower left\", title=\"Classes\")\nax.add_artist(legend1)\n\n# produce a legend with a cross-section of sizes from the scatter\nhandles, labels = scatter.legend_elements(prop=\"sizes\", alpha=0.6)\nlegend2 = ax.legend(handles, labels, loc=\"upper right\", title=\"Sizes\")\n\nplt.show()"}]},{"title":"Customizing Legend Elements","body":["We can further customize the legend elements by using additional arguments in the PathCollection.legend_elements method. For example, we can specify the number of legend entries to be created and how they should be labeled."],"code":[{"lang":"python","text":"volume = np.random.rayleigh(27, size=40)\namount = np.random.poisson(10, size=40)\nranking = np.random.normal(size=40)\nprice = np.random.uniform(1, 10, size=40)\n\nfig, ax = plt.subplots()\n\n# Because the price is much too small when being provided as size for ``s``,\n# we normalize it to some useful point sizes, s=0.3*(price*3)**2\nscatter = ax.scatter(volume, amount, c=ranking, s=0.3*(price*3)**2,\n                     vmin=-3, vmax=3, cmap=\"Spectral\")\n\n# Produce a legend for the ranking (colors). Even though there are 40 different\n# rankings, we only want to show 5 of them in the legend.\nlegend1 = ax.legend(*scatter.legend_elements(num=5),\n                    loc=\"upper left\", title=\"Ranking\")\nax.add_artist(legend1)\n\n# Produce a legend for the price (sizes). Because we want to show the prices\n# in dollars, we use the *func* argument to supply the inverse of the function\n# used to calculate the sizes from above. The *fmt* ensures to show the price\n# in dollars. Note how we target at 5 elements here, but obtain only 4 in the\n# created legend due to the automatic round prices that are chosen for us.\nkw = dict(prop=\"sizes\", num=5, color=scatter.cmap(0.7), fmt=\"$ {x:.2f}\",\n          func=lambda s: np.sqrt(s/.3)/3)\nlegend2 = ax.legend(*scatter.legend_elements(**kw),\n                    loc=\"lower right\", title=\"Price\")\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"volume = np.random.rayleigh(27, size=40)\namount = np.random.poisson(10, size=40)\nranking = np.random.normal(size=40)\nprice = np.random.uniform(1, 10, size=40)\n\nfig, ax = plt.subplots()\n\n# Because the price is much too small when being provided as size for ``s``,\n# we normalize it to some useful point sizes, s=0.3*(price*3)**2\nscatter = ax.scatter(volume, amount, c=ranking, s=0.3*(price*3)**2,\n                     vmin=-3, vmax=3, cmap=\"Spectral\")\n\n# Produce a legend for the ranking (colors). Even though there are 40 different\n# rankings, we only want to show 5 of them in the legend.\nlegend1 = ax.legend(*scatter.legend_elements(num=5),\n                    loc=\"upper left\", title=\"Ranking\")\nax.add_artist(legend1)\n\n# Produce a legend for the price (sizes). Because we want to show the prices\n# in dollars, we use the *func* argument to supply the inverse of the function\n# used to calculate the sizes from above. The *fmt* ensures to show the price\n# in dollars. Note how we target at 5 elements here, but obtain only 4 in the\n# created legend due to the automatic round prices that are chosen for us.\nkw = dict(prop=\"sizes\", num=5, color=scatter.cmap(0.7), fmt=\"$ {x:.2f}\",\n          func=lambda s: np.sqrt(s/.3)/3)\nlegend2 = ax.legend(*scatter.legend_elements(**kw),\n                    loc=\"lower right\", title=\"Price\")\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-3d-scatterplot-with-python-matplotlib":{"intro":"This tutorial will guide you on how to create a 3D scatterplot using Python's Matplotlib library. The scatterplot is a graphical representation of the relationship between three variables. It is a useful tool for identifying patterns and trends in complex data.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","To create a 3D scatterplot, we will be using the Matplotlib library. We will also be using the NumPy library to generate random data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Set up the data","body":["We will generate two sets of data with random values using the NumPy library. One set will represent the x and y coordinates, and the other set will represent the z coordinate."],"code":[{"lang":"python","text":"def randrange(n, vmin, vmax):\n    \"\"\"\n    Helper function to make an array of random numbers having shape (n, )\n    with each number distributed Uniform(vmin, vmax).\n    \"\"\"\n    return (vmax - vmin)*np.random.rand(n) + vmin\n\nn = 100\n\nfor m, zlow, zhigh in [('o', -50, -25), ('^', -30, -5)]:\n    xs = randrange(n, 23, 32)\n    ys = randrange(n, 0, 100)\n    zs = randrange(n, zlow, zhigh)"}]},{"title":"Create the figure and subplot","body":["We will create the figure and subplot using the add_subplot function from the Matplotlib library. We will also set the projection to '3d' to create a 3D plot."],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(projection='3d')"}]},{"title":"Create the scatterplot","body":["We will create the scatterplot using the scatter function from the Matplotlib library. We will pass in the x, y, and z coordinates as well as the marker style."],"code":[{"lang":"python","text":"ax.scatter(xs, ys, zs, marker=m)"}]},{"title":"Set the axis labels","body":["We will set the labels for the x, y, and z axes using the set_xlabel, set_ylabel, and set_zlabel functions from the Matplotlib library."],"code":[{"lang":"python","text":"ax.set_xlabel('X Label')\nax.set_ylabel('Y Label')\nax.set_zlabel('Z Label')"}]},{"title":"Display the plot","body":["We will display the plot using the show function from the Matplotlib library."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-secondary-axis":{"intro":"Matplotlib is a popular data visualization library in Python. Sometimes, we need to plot two different scales of data on the same graph, this is when the concept of a secondary axis comes into play. In this lab, we will learn how to create a secondary axis in Matplotlib.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","We will start by importing the necessary libraries, which are matplotlib, numpy, and datetime."],"code":[{"lang":"python","text":"import datetime\nimport matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.dates as mdates\nfrom matplotlib.ticker import AutoMinorLocator"}]},{"title":"Plot the data","body":["We will create a simple sine wave to demonstrate the use of a secondary axis. We will plot the sine wave using degrees as the x-axis."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(layout='constrained')\nx = np.arange(0, 360, 1)\ny = np.sin(2 * x * np.pi / 180)\nax.plot(x, y)\nax.set_xlabel('angle [degrees]')\nax.set_ylabel('signal')\nax.set_title('Sine wave')"}]},{"title":"Create the Secondary Axis","body":["We will now create the secondary axis and convert the x-axis from degrees to radians. We will use deg2rad as the forward function and rad2deg as the inverse function."],"code":[{"lang":"python","text":"def deg2rad(x):\n    return x * np.pi / 180\n\ndef rad2deg(x):\n    return x * 180 / np.pi\n\nsecax = ax.secondary_xaxis('top', functions=(deg2rad, rad2deg))\nsecax.set_xlabel('angle [rad]')"}]},{"title":"Plot another example","body":["We will now plot another example of converting from wavenumber to wavelength in a log-log scale. We will use a random spectrum for this example."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(layout='constrained')\nx = np.arange(0.02, 1, 0.02)\nnp.random.seed(19680801)\ny = np.random.randn(len(x)) ** 2\nax.loglog(x, y)\nax.set_xlabel('f [Hz]')\nax.set_ylabel('PSD')\nax.set_title('Random spectrum')"}]},{"title":"Create the Secondary X-Axis","body":["We will create the secondary x-axis and convert from frequency to period. We will use one_over as the forward function and inverse as the inverse function."],"code":[{"lang":"python","text":"def one_over(x):\n    \"\"\"Vectorized 1/x, treating x==0 manually\"\"\"\n    x = np.array(x, float)\n    near_zero = np.isclose(x, 0)\n    x[near_zero] = np.inf\n    x[~near_zero] = 1 / x[~near_zero]\n    return x\n\n# the function \"1/x\" is its own inverse\ninverse = one_over\n\nsecax = ax.secondary_xaxis('top', functions=(one_over, inverse))\nsecax.set_xlabel('period [s]')"}]},{"title":"Create the Secondary Y-Axis","body":["We will create a third example of relating the axes in a transform that is ad-hoc from the data, and is derived empirically. In this case, we will set the forward and inverse transforms functions to be linear interpolations from the one data set to the other."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(layout='constrained')\nxdata = np.arange(1, 11, 0.4)\nydata = np.random.randn(len(xdata))\nax.plot(xdata, ydata, label='Plotted data')\n\nxold = np.arange(0, 11, 0.2)\n# fake data set relating x coordinate to another data-derived coordinate.\n# xnew must be monotonic, so we sort...\nxnew = np.sort(10 * np.exp(-xold / 4) + np.random.randn(len(xold)) / 3)\n\nax.plot(xold[3:], xnew[3:], label='Transform data')\nax.set_xlabel('X [m]')\nax.legend()\n\ndef forward(x):\n    return np.interp(x, xold, xnew)\n\ndef inverse(x):\n    return np.interp(x, xnew, xold)\n\nsecax = ax.secondary_xaxis('top', functions=(forward, inverse))\nsecax.xaxis.set_minor_locator(AutoMinorLocator())\nsecax.set_xlabel('$X_{other}$')"}]},{"title":"Create Multiple Axes","body":["We will now create a final example that translates np.datetime64 to yearday on the x-axis and from Celsius to Fahrenheit on the y-axis. We will also add a third y-axis and place it using a float for the location argument."],"code":[{"lang":"python","text":"dates = [datetime.datetime(2018, 1, 1) + datetime.timedelta(hours=k * 6)\n         for k in range(240)]\ntemperature = np.random.randn(len(dates)) * 4 + 6.7\nfig, ax = plt.subplots(layout='constrained')\n\nax.plot(dates, temperature)\nax.set_ylabel(r'$T\\ [^oC]$')\nplt.xticks(rotation=70)\n\ndef date2yday(x):\n    \"\"\"Convert matplotlib datenum to days since 2018-01-01.\"\"\"\n    y = x - mdates.date2num(datetime.datetime(2018, 1, 1))\n    return y\n\ndef yday2date(x):\n    \"\"\"Return a matplotlib datenum for *x* days after 2018-01-01.\"\"\"\n    y = x + mdates.date2num(datetime.datetime(2018, 1, 1))\n    return y\n\nsecax_x = ax.secondary_xaxis('top', functions=(date2yday, yday2date))\nsecax_x.set_xlabel('yday [2018]')\n\ndef celsius_to_fahrenheit(x):\n    return x * 1.8 + 32\n\ndef fahrenheit_to_celsius(x):\n    return (x - 32) / 1.8\n\nsecax_y = ax.secondary_yaxis(\n    'right', functions=(celsius_to_fahrenheit, fahrenheit_to_celsius))\nsecax_y.set_ylabel(r'$T\\ [^oF]$')\n\ndef celsius_to_anomaly(x):\n    return (x - np.mean(temperature))\n\ndef anomaly_to_celsius(x):\n    return (x + np.mean(temperature))\n\n# use of a float for the position:\nsecax_y2 = ax.secondary_yaxis(\n    1.2, functions=(celsius_to_anomaly, anomaly_to_celsius))\nsecax_y2.set_ylabel(r'$T - \\overline{T}\\ [^oC]$')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"dates = [datetime.datetime(2018, 1, 1) + datetime.timedelta(hours=k * 6)\n         for k in range(240)]\ntemperature = np.random.randn(len(dates)) * 4 + 6.7\nfig, ax = plt.subplots(layout='constrained')\n\nax.plot(dates, temperature)\nax.set_ylabel(r'$T\\ [^oC]$')\nplt.xticks(rotation=70)\n\ndef date2yday(x):\n    \"\"\"Convert matplotlib datenum to days since 2018-01-01.\"\"\"\n    y = x - mdates.date2num(datetime.datetime(2018, 1, 1))\n    return y\n\ndef yday2date(x):\n    \"\"\"Return a matplotlib datenum for *x* days after 2018-01-01.\"\"\"\n    y = x + mdates.date2num(datetime.datetime(2018, 1, 1))\n    return y\n\nsecax_x = ax.secondary_xaxis('top', functions=(date2yday, yday2date))\nsecax_x.set_xlabel('yday [2018]')\n\ndef celsius_to_fahrenheit(x):\n    return x * 1.8 + 32\n\ndef fahrenheit_to_celsius(x):\n    return (x - 32) / 1.8\n\nsecax_y = ax.secondary_yaxis(\n    'right', functions=(celsius_to_fahrenheit, fahrenheit_to_celsius))\nsecax_y.set_ylabel(r'$T\\ [^oF]$')\n\ndef celsius_to_anomaly(x):\n    return (x - np.mean(temperature))\n\ndef anomaly_to_celsius(x):\n    return (x + np.mean(temperature))\n\n# use of a float for the position:\nsecax_y2 = ax.secondary_yaxis(\n    1.2, functions=(celsius_to_anomaly, anomaly_to_celsius))\nsecax_y2.set_ylabel(r'$T - \\overline{T}\\ [^oC]$')"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-plotting-exponential-decay-with-matplotlib-s":{"intro":"This tutorial will guide you through how to assign a log scale for the x-axis using matplotlib.axes.Axes.semilogx in Python Matplotlib. A logarithmic scale is useful when the data you want to plot spans several orders of magnitude. In this tutorial, we will use an example of plotting exponential decay as a function of time.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","We will use numpy and matplotlib libraries in this tutorial."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate data","body":["We will generate data for exponential decay function np.exp(-t / 5.0) using numpy library."],"code":[{"lang":"python","text":"dt = 0.01\nt = np.arange(dt, 20.0, dt)"}]},{"title":"Create a plot and set x-axis to logarithmic scale","body":["Create a plot and set x-axis to logarithmic scale","We create a figure and axes object using subplots() method. We then plot the exponential decay function using semilogx() method and set the x-axis to a logarithmic scale using set_xscale() method. We also add a grid to the plot using grid() method."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\nax.semilogx(t, np.exp(-t / 5.0))\nax.set_xscale('log')\nax.grid()"}]},{"title":"Show the plot","body":["We use show() method to display the plot."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-ways-to-set-a-color-s-alpha-value":{"intro":"This lab is about setting a color's alpha value using the Python Matplotlib library. Alpha value is a measure of transparency, where a value of 0 means completely transparent and a value of 1 means completely opaque. We will explore two ways to set alpha value in Matplotlib: using the alpha keyword argument and using the (matplotlib_color, alpha) color format.","steps":[{"title":"Understanding Alpha Values in Matplotlib","body":["Understanding Alpha Values in Matplotlib","In this cell, we'll import the necessary libraries and create two overlapping circles with different alpha values to demonstrate transparency.","You should see two overlapping circles:","• The blue circle on the left is completely opaque (alpha=1.0) • The red circle on the right is semi-transparent (alpha=0.5)"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Create a figure and an axes\nfig, ax = plt.subplots(figsize=(6, 4))\n\n# Create a circle with alpha=1.0 (completely opaque)\ncircle1 = plt.Circle((0.5, 0.5), 0.3, color='blue', alpha=1.0, label='Opaque (alpha=1.0)')\n\n# Create a circle with alpha=0.5 (semi-transparent)\ncircle2 = plt.Circle((0.7, 0.5), 0.3, color='red', alpha=0.5, label='Semi-transparent (alpha=0.5)')\n\n# Add circles to the axes\nax.add_patch(circle1)\nax.add_patch(circle2)\n\n# Set axis limits\nax.set_xlim(0, 1.2)\nax.set_ylim(0, 1)\n\n# Add a title and legend\nax.set_title('Demonstrating Alpha Values in Matplotlib')\nax.legend(loc='upper right')\n\n# Show the plot\nplt.show()"}]},{"title":"Creating a Bar Chart with Uniform Alpha Value","body":["Creating a Bar Chart with Uniform Alpha Value","In this step, we will create a bar chart where all bars have the same transparency level using the alpha keyword argument.","Creating the Bar Chart with Uniform Alpha","Enter and run the following code in the new cell:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Set a random seed for reproducibility\nnp.random.seed(19680801)\n\n# Create a figure and an axes\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Generate data\nx_values = list(range(20))  # 0 to 19\ny_values = np.random.randn(20)  # 20 random values from standard normal distribution\n\n# Determine bar colors based on y-values (green for positive, red for negative)\nfacecolors = ['green' if y > 0 else 'red' for y in y_values]\nedgecolors = facecolors  # Same color for edges\n\n# Create the bar chart with alpha=0.5 for all bars\nax.bar(x_values, y_values, color=facecolors, edgecolor=edgecolors, alpha=0.5)\n\n# Add a title and labels\nax.set_title(\"Bar Chart with Uniform Alpha Value (alpha=0.5)\")\nax.set_xlabel(\"X Values\")\nax.set_ylabel(\"Y Values\")\n\n# Add a grid for better readability\nax.grid(True, linestyle='--', alpha=0.7)\n\n# Show the plot\nplt.show()"}]},{"title":"Creating a Bar Chart with Varying Alpha Values","body":["Creating a Bar Chart with Varying Alpha Values","In this step, we'll use the (matplotlib_color, alpha) tuple format to assign different transparency levels to each bar based on its data value.","Creating the Bar Chart with Varying Alpha Values","Enter and run the following code in the new cell:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Set a random seed for reproducibility\nnp.random.seed(19680801)\n\n# Create a figure and an axes\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Generate data (using the same data as in Step 2 for comparison)\nx_values = list(range(20))  # 0 to 19\ny_values = np.random.randn(20)  # 20 random values from standard normal distribution\n\n# Determine bar colors based on y-values (green for positive, red for negative)\nfacecolors = ['green' if y > 0 else 'red' for y in y_values]\nedgecolors = facecolors  # Same color for edges\n\n# Calculate alpha values based on the absolute y-values\n# Normalize y values to get alpha values between 0.2 and 1.0\nabs_y = [abs(y) for y in y_values]\nmax_abs_y = max(abs_y)\nface_alphas = [0.2 + 0.8 * (val / max_abs_y) for val in abs_y]\n\n# Create color-alpha tuples for each bar\ncolors_with_alphas = list(zip(facecolors, face_alphas))\n\n# Create the bar chart with varying alpha values\nax.bar(x_values, y_values, color=colors_with_alphas, edgecolor=edgecolors)\n\n# Add a title and labels\nax.set_title(\"Bar Chart with Varying Alpha Values Based on Bar Height\")\nax.set_xlabel(\"X Values\")\nax.set_ylabel(\"Y Values\")\n\n# Add a grid for better readability\nax.grid(True, linestyle='--', alpha=0.7)\n\n# Show the plot\nplt.show()"}]},{"title":"Creating a Scatter Plot with Alpha Values","body":["Creating a Scatter Plot with Alpha Values","In this step, we'll apply our knowledge of alpha values to create a scatter plot. This will demonstrate how transparency can help visualize data density in scatter plots with overlapping points.","Creating a Scatter Plot with Transparency","Enter and run the following code in the new cell:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Set a random seed for reproducibility\nnp.random.seed(19680801)\n\n# Create a figure and an axes\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Create two clusters of points\ncluster1_x = np.random.normal(0.3, 0.15, 500)\ncluster1_y = np.random.normal(0.3, 0.15, 500)\n\ncluster2_x = np.random.normal(0.7, 0.15, 500)\ncluster2_y = np.random.normal(0.7, 0.15, 500)\n\n# Combine the clusters\nx = np.concatenate([cluster1_x, cluster2_x])\ny = np.concatenate([cluster1_y, cluster2_y])\n\n# Create a scatter plot with alpha=0.5\nscatter = ax.scatter(x, y, s=30, c='blue', alpha=0.5)\n\n# Add a title and labels\nax.set_title(\"Scatter Plot with Alpha=0.5 Showing Data Density\")\nax.set_xlabel(\"X\")\nax.set_ylabel(\"Y\")\n\n# Set axis limits\nax.set_xlim(0, 1)\nax.set_ylim(0, 1)\n\n# Add a grid\nax.grid(True, linestyle='--', alpha=0.7)\n\n# Show the plot\nplt.show()"}]},{"title":"Creating a Combined Visualization with Different Alpha Techniques","body":["Creating a Combined Visualization with Different Alpha Techniques","In this final step, we'll combine multiple techniques to create a more complex visualization that demonstrates both uniform and varying alpha values in one plot.","Creating a Combined Visualization","Enter and run the following code in the new cell:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Set a random seed for reproducibility\nnp.random.seed(19680801)\n\n# Create a figure with two subplots side by side\nfig, (ax1, ax2) = plt.subplots(1, 2, figsize=(14, 6))\n\n# Generate some common data\nx = np.linspace(0, 10, 100)\ny1 = np.sin(x)\ny2 = np.cos(x)\ny3 = np.sin(x) * np.cos(x)\n\n# First subplot: Fixed alpha for all lines\nax1.plot(x, y1, color='red', linewidth=2, label='sin(x)', alpha=0.7)\nax1.plot(x, y2, color='blue', linewidth=2, label='cos(x)', alpha=0.7)\nax1.plot(x, y3, color='green', linewidth=2, label='sin(x)cos(x)', alpha=0.7)\n\n# Add title and legend to first subplot\nax1.set_title(\"Multiple Lines with Uniform Alpha\")\nax1.set_xlabel(\"x\")\nax1.set_ylabel(\"y\")\nax1.legend()\nax1.grid(True, linestyle='--', alpha=0.5)\n\n# Second subplot: Scatter plot with varying alpha based on y-value\nsizes = np.abs(y3 * 100) + 10  # Vary point sizes based on y3\ncolors = y3  # Use y3 values for coloring\n\n# Calculate varying alpha values between 0.3 and 1.0 based on absolute y3 values\nalphas = 0.3 + 0.7 * (np.abs(y3) / max(np.abs(y3)))\n\n# Create a scatter plot with varying sizes, colors, and alphas\nscatter = ax2.scatter(x, y3, s=sizes, c=colors, cmap='viridis',\n                     alpha=alphas)\n\n# Add title and labels to second subplot\nax2.set_title(\"Scatter Plot with Varying Alpha Based on Y-Value\")\nax2.set_xlabel(\"x\")\nax2.set_ylabel(\"sin(x)cos(x)\")\nax2.grid(True, linestyle='--', alpha=0.5)\n\n# Add a colorbar to the second subplot\ncbar = plt.colorbar(scatter, ax=ax2)\ncbar.set_label('Value of sin(x)cos(x)')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Set a random seed for reproducibility\nnp.random.seed(19680801)\n\n# Create a figure with two subplots side by side\nfig, (ax1, ax2) = plt.subplots(1, 2, figsize=(14, 6))\n\n# Generate some common data\nx = np.linspace(0, 10, 100)\ny1 = np.sin(x)\ny2 = np.cos(x)\ny3 = np.sin(x) * np.cos(x)\n\n# First subplot: Fixed alpha for all lines\nax1.plot(x, y1, color='red', linewidth=2, label='sin(x)', alpha=0.7)\nax1.plot(x, y2, color='blue', linewidth=2, label='cos(x)', alpha=0.7)\nax1.plot(x, y3, color='green', linewidth=2, label='sin(x)cos(x)', alpha=0.7)\n\n# Add title and legend to first subplot\nax1.set_title(\"Multiple Lines with Uniform Alpha\")\nax1.set_xlabel(\"x\")\nax1.set_ylabel(\"y\")\nax1.legend()\nax1.grid(True, linestyle='--', alpha=0.5)\n\n# Second subplot: Scatter plot with varying alpha based on y-value\nsizes = np.abs(y3 * 100) + 10  # Vary point sizes based on y3\ncolors = y3  # Use y3 values for coloring\n\n# Calculate varying alpha values between 0.3 and 1.0 based on absolute y3 values\nalphas = 0.3 + 0.7 * (np.abs(y3) / max(np.abs(y3)))\n\n# Create a scatter plot with varying sizes, colors, and alphas\nscatter = ax2.scatter(x, y3, s=sizes, c=colors, cmap='viridis',\n                     alpha=alphas)\n\n# Add title and labels to second subplot\nax2.set_title(\"Scatter Plot with Varying Alpha Based on Y-Value\")\nax2.set_xlabel(\"x\")\nax2.set_ylabel(\"sin(x)cos(x)\")\nax2.grid(True, linestyle='--', alpha=0.5)\n\n# Add a colorbar to the second subplot\ncbar = plt.colorbar(scatter, ax=ax2)\ncbar.set_label('Value of sin(x)cos(x)')"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-set-and-get":{"intro":"Matplotlib is a Python library used for creating static, animated, and interactive visualizations in Python. It allows you to create a wide range of visualizations such as line charts, scatter plots, bar charts, histograms, and 3D plots. In this tutorial, we will learn how to use the pyplot interface to set and get object properties for visualizing data.","steps":[{"title":"Installing Matplotlib","body":[],"code":[{"lang":"python","text":"!pip install matplotlib"}]},{"title":"Importing Matplotlib","body":["To use Matplotlib, we need to import it in our Python script using the following import statement."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Setting Properties","body":["The pyplot interface allows us to set and get object properties for visualizing data. We can use the setp method to set the properties of an object. For example, to set the linestyle of a line to dashed, we use the following code:","If we want to know the valid types of arguments, we can provide the name of the property we want to set without a value:","This will return the following output:","If we want to see all the properties that can be set, and their possible values, we can use the following code:"],"code":[{"lang":"python","text":"line, = plt.plot([1, 2, 3])\nplt.setp(line, linestyle='--')"},{"lang":"python","text":"plt.setp(line, 'linestyle')"},{"lang":"text","text":"linestyle: {'-', '--', '-.', ':', '', (offset, on-off-seq), ...}"}]},{"title":"Getting Properties","body":["We can use the getp method to get the properties of an object. We can use it to query the value of a single attribute:","This will return the value of the linewidth property of the line object.","We can also use getp to get all the attribute/value pairs of an object:","This will return a long list of all the properties and their values."],"code":[{"lang":"python","text":"plt.getp(line, 'linewidth')"},{"lang":"python","text":"plt.getp(line)"}]},{"title":"Aliases","body":["To reduce keystrokes in interactive mode, a number of properties have short aliases, e.g., 'lw' for 'linewidth' and 'mec' for 'markeredgecolor'. When calling set or get in introspection mode, these properties will be listed as 'fullname' or 'aliasname'."],"code":[{"lang":"python","text":"l1, l2 = plt.plot([1, 2, 3], [2, 3, 4], [1, 2, 3], [3, 4, 5])\nplt.setp(l1, linewidth=2, color='r')\nplt.setp(l2, linewidth=1, color='g')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"l1, l2 = plt.plot([1, 2, 3], [2, 3, 4], [1, 2, 3], [3, 4, 5])\nplt.setp(l1, linewidth=2, color='r')\nplt.setp(l2, linewidth=1, color='g')"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-shaded-relief-plots-with-python":{"intro":"In this lab, we will learn how to create shaded relief plots using Python Matplotlib. Shaded relief plots are useful for visualizing terrain data, as they use shading to represent variations in elevation.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib import cbook\nfrom matplotlib.colors import LightSource"}]},{"title":"Load Data","body":["Next, we will load the sample data that we will use for this tutorial. We will use the jacksboro_fault_dem.npz file, which contains elevation data."],"code":[{"lang":"python","text":"dem = cbook.get_sample_data('jacksboro_fault_dem.npz')\nelev = dem['elevation']"}]},{"title":"Create Shaded Relief Plots","body":["We will now create the shaded relief plots using the LightSource class. We will create two subplots, one with a colormapped data and the other with illumination intensity.","We will create two more subplots, one with the blend_mode set to \"hsv\" and the other set to \"overlay\"."],"code":[{"lang":"python","text":"# Illuminate the scene from the northwest\nls = LightSource(azdeg=315, altdeg=45)\n\nfig, axs = plt.subplots(ncols=2, nrows=2)\nfor ax in axs.flat:\n    ax.set(xticks=[], yticks=[])\n\naxs[0, 0].imshow(z, cmap=cmap)\naxs[0, 0].set(xlabel='Colormapped Data')\n\naxs[0, 1].imshow(ls.hillshade(z, vert_exag=ve), cmap='gray')\naxs[0, 1].set(xlabel='Illumination Intensity')"},{"lang":"python","text":"rgb = ls.shade(z, cmap=cmap, vert_exag=ve, blend_mode='hsv')\naxs[1, 0].imshow(rgb)\naxs[1, 0].set(xlabel='Blend Mode: \"hsv\" (default)')\n\nrgb = ls.shade(z, cmap=cmap, vert_exag=ve, blend_mode='overlay')\naxs[1, 1].imshow(rgb)\naxs[1, 1].set(xlabel='Blend Mode: \"overlay\"')"}]},{"title":"Display the Plots","body":["Finally, we will display the plots using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-plot-sharing":{"intro":"When creating multiple plots that share a common axis, you may want to ensure that when you zoom in or out on one plot, the other plots update as well. In this lab, we will explore how to use the sharex and sharey attributes in Matplotlib to create plots that share an axis.","steps":[{"title":"Import Required Libraries","body":["The first step is to import the required libraries. In this example, we will be using numpy and matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data","body":["Next, we need to create some data to plot. In this example, we will create two sets of data, sin(2*pi*t) and sin(4*pi*t)."],"code":[{"lang":"python","text":"t = np.arange(0, 10, 0.01)"}]},{"title":"Create the First Plot","body":["Now, let's create the first plot using subplot. subplot takes three arguments: the number of rows, the number of columns, and the plot number. In this example, we will create a plot with 2 rows and 1 column (211), which means the first plot will be in the top row."],"code":[{"lang":"python","text":"ax1 = plt.subplot(211)\nax1.plot(t, np.sin(2*np.pi*t))"}]},{"title":"Create the Second Plot","body":["Next, we will create the second plot. We will use subplot again, but this time we will set the sharex attribute to the first plot (ax1). This ensures that the second plot will share the same x-axis as the first plot."],"code":[{"lang":"python","text":"ax2 = plt.subplot(212, sharex=ax1)\nax2.plot(t, np.sin(4*np.pi*t))"}]},{"title":"Show the Plots","body":["Finally, we can show the plots using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-shared-axis":{"intro":"In this lab, you will learn how to create plots with shared axes using the Matplotlib library in Python. Shared axes can be useful when you want to compare different data sets with the same scale.","steps":[{"title":"Import Matplotlib and NumPy Libraries","body":["Import Matplotlib and NumPy Libraries","We need to import the Matplotlib and NumPy libraries to create the plots. NumPy is a library for the Python programming language, adding support for large, multi-dimensional arrays and matrices."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data for the Plots","body":["We need to create data for the plots to visualize. In this example, we will create three different datasets using NumPy."],"code":[{"lang":"python","text":"t = np.arange(0.01, 5.0, 0.01)\ns1 = np.sin(2 * np.pi * t)\ns2 = np.exp(-t)\ns3 = np.sin(4 * np.pi * t)"}]},{"title":"Create the Subplots","body":["We can create subplots using the plt.subplot() method. In this example, we will create three subplots with the first subplot taking up the first row and all three columns, and the second and third subplots taking up the second and third row, respectively, and sharing the x-axis with the first subplot."],"code":[{"lang":"python","text":"ax1 = plt.subplot(311)\nax2 = plt.subplot(312, sharex=ax1)\nax3 = plt.subplot(313, sharex=ax1, sharey=ax1)"}]},{"title":"Plot the Data","body":["We can now plot the data on each of the subplots using the plt.plot() method."],"code":[{"lang":"python","text":"ax1.plot(t, s1)\nax2.plot(t, s2)\nax3.plot(t, s3)"}]},{"title":"Customize the Tick Labels","body":["We can customize the tick labels on the various axes using the plt.tick_params() method. In this example, we will customize the tick labels on the x-axis of the first subplot to be smaller."],"code":[{"lang":"python","text":"plt.tick_params('x', labelsize=6)"}]},{"title":"Remove Tick Labels","body":["We can remove tick labels from a specific subplot by altering the visibility of the labels using the ax.get_xticklabels() method. In this example, we will remove the tick labels on the x-axis of the second subplot."],"code":[{"lang":"python","text":"plt.tick_params('x', labelbottom=False)"}]},{"title":"Set the Axis Limits","body":["We can set the axis limits on each subplot using the plt.xlim() method. In this example, we will set the x-axis limits on the third subplot to be from 0.01 to 5.0."],"code":[{"lang":"python","text":"plt.xlim(0.01, 5.0)"}]},{"title":"Display the Plots","body":["We can now display the plots using the plt.show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-simple-anchored-artists":{"intro":"In this lab, you will learn how to use the anchored helper classes found in Matplotlib's offsetbox and mpl_toolkits.axes_grid1. You will create a figure that contains text boxes, a circle, and a size bar using these classes.","steps":[{"title":"Import Libraries","body":["To get started, you will need to import Matplotlib and the necessary modules."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.offsetbox import AnchoredText\nfrom matplotlib.patches import Circle\nfrom mpl_toolkits.axes_grid1.anchored_artists import AnchoredDrawingArea, AnchoredSizeBar"}]},{"title":"Create the Figure","body":["Create a figure and axis object using Matplotlib's subplots() function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.set_aspect(1.)"}]},{"title":"Add Text Boxes","body":["Add two text boxes to the figure, anchored by different corners to the upper-left corner of the figure."],"code":[{"lang":"python","text":"at = AnchoredText(\"Figure 1a\",\n                  loc='upper left', prop=dict(size=8), frameon=True,\n                  )\nat.patch.set_boxstyle(\"round,pad=0.,rounding_size=0.2\")\nax.add_artist(at)\n\nat2 = AnchoredText(\"Figure 1(b)\",\n                   loc='lower left', prop=dict(size=8), frameon=True,\n                   bbox_to_anchor=(0., 1.),\n                   bbox_transform=ax.transAxes\n                   )\nat2.patch.set_boxstyle(\"round,pad=0.,rounding_size=0.2\")\nax.add_artist(at2)"}]},{"title":"Draw a Circle","body":["Draw a circle in axis coordinates."],"code":[{"lang":"python","text":"ada = AnchoredDrawingArea(20, 20, 0, 0,\n                          loc='upper right', pad=0., frameon=False)\np = Circle((10, 10), 10)\nada.da.add_artist(p)\nax.add_artist(ada)"}]},{"title":"Add a Size Bar","body":["Draw a horizontal bar with a length of 0.1 in data coordinates, with a fixed label underneath."],"code":[{"lang":"python","text":"asb = AnchoredSizeBar(ax.transData,\n                      0.1,\n                      r\"1$^{\\prime}$\",\n                      loc='lower center',\n                      pad=0.1, borderpad=0.5, sep=5,\n                      frameon=False)\nax.add_artist(asb)"}]},{"title":"Display the Figure","body":["Display the figure using Matplotlib's show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-animated-line-plot":{"intro":"This tutorial will guide you through the process of creating an animated line plot using Python Matplotlib library. The line plot will display a sine wave with a changing amplitude over time.","steps":[{"title":"Import Libraries","body":["The first step is to import the necessary libraries. We will be using Matplotlib for creating the plot and NumPy for generating data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.animation as animation"}]},{"title":"Initialize the Figure and Axes","body":["Initialize the Figure and Axes","Next, we need to initialize the figure and axes for the plot. This can be done using the subplots() function from Matplotlib."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"}]},{"title":"Generate Data","body":["In this step, we will generate the data for the line plot. We will be using the NumPy arange() function to generate an array of values for the x-axis, and the sin() function to generate an array of y-axis values for a sine wave."],"code":[{"lang":"python","text":"x = np.arange(0, 2*np.pi, 0.01)\nline, = ax.plot(x, np.sin(x))"}]},{"title":"Define the Animation Function","body":["The animation function will be called by the FuncAnimation() function and will be used to update the plot with new data. In this example, we will be updating the y-axis values of the line plot with a sine wave that has a changing amplitude over time."],"code":[{"lang":"python","text":"def animate(i):\n    line.set_ydata(np.sin(x + i / 50))  # update the data.\n    return line,"}]},{"title":"Create the Animation Object","body":["Now we can create the animation object using the FuncAnimation() function. We will pass in the figure object, the animation function, the update interval, and the number of frames to be saved."],"code":[{"lang":"python","text":"ani = animation.FuncAnimation(\n    fig, animate, interval=20, blit=True, save_count=50)"}]},{"title":"Display the Plot","body":["Finally, we can display the plot using the show() function from Matplotlib."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-custom-matplotlib-grid-axes-creation":{"intro":"In this lab, we will learn how to create a custom grid of axes with Matplotlib using the mpl_toolkits.axes_grid1 module. We will create two examples: one with fixed axes sizes and paddings, and another with scalable axes sizes and fixed paddings.","steps":[{"title":"Importing Required Libraries","body":["We will start by importing the required libraries: matplotlib.pyplot for visualization and mpl_toolkits.axes_grid1 for creating the custom grid of axes."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.axes_grid1 import Divider, Size"}]},{"title":"Defining Helper Function","body":["We will define a helper function label_axes() that will be used to place a label at the center of an axes and remove the axis ticks."],"code":[{"lang":"python","text":"def label_axes(ax, text):\n    \"\"\"Place a label at the center of an Axes, and remove the axis ticks.\"\"\"\n    ax.text(.5, .5, text, transform=ax.transAxes,\n            horizontalalignment=\"center\", verticalalignment=\"center\")\n    ax.tick_params(bottom=False, labelbottom=False,\n                   left=False, labelleft=False)"}]},{"title":"Creating a Custom Grid of Axes with Fixed Sizes and Paddings","body":["Creating a Custom Grid of Axes with Fixed Sizes and Paddings","We will create a custom grid of axes with fixed sizes and paddings. We will use the Divider class to divide the axes rectangle into a grid with sizes specified by horiz * vert. We will then add four axes to the figure using the add_axes() method and specify the positions of each axes using the new_locator() method of the Divider class."],"code":[{"lang":"python","text":"# Sizes are in inches.\nhoriz = [Size.Fixed(1.), Size.Fixed(.5), Size.Fixed(1.5), Size.Fixed(.5)]\nvert = [Size.Fixed(1.5), Size.Fixed(.5), Size.Fixed(1.)]\n\nrect = (0.1, 0.1, 0.8, 0.8)\nfig = plt.figure(figsize=(6, 6))\nfig.suptitle(\"Fixed axes sizes, fixed paddings\")\n\ndiv = Divider(fig, rect, horiz, vert, aspect=False)\n\n# The rect parameter will actually be ignored and overridden by axes_locator.\nax1 = fig.add_axes(rect, axes_locator=div.new_locator(nx=0, ny=0))\nlabel_axes(ax1, \"nx=0, ny=0\")\nax2 = fig.add_axes(rect, axes_locator=div.new_locator(nx=0, ny=2))\nlabel_axes(ax2, \"nx=0, ny=2\")\nax3 = fig.add_axes(rect, axes_locator=div.new_locator(nx=2, ny=2))\nlabel_axes(ax3, \"nx=2, ny=2\")\nax4 = fig.add_axes(rect, axes_locator=div.new_locator(nx=2, nx1=4, ny=0))\nlabel_axes(ax4, \"nx=2, nx1=4, ny=0\")\n\nplt.show()"}]},{"title":"Creating a Custom Grid of Axes with Scalable Sizes and Fixed Paddings","body":["Creating a Custom Grid of Axes with Scalable Sizes and Fixed Paddings","We will create another custom grid of axes with scalable sizes and fixed paddings. We will use the Size.Scaled() option to specify axes sizes that scale with the figure size. The remaining steps are similar to the previous example."],"code":[{"lang":"python","text":"# Sizes are in inches.\nhoriz = [Size.Scaled(1.5), Size.Fixed(.5), Size.Scaled(1.), Size.Scaled(.5)]\nvert = [Size.Scaled(1.), Size.Fixed(.5), Size.Scaled(1.5)]\n\nrect = (0.1, 0.1, 0.8, 0.8)\nfig = plt.figure(figsize=(6, 6))\nfig.suptitle(\"Scalable axes sizes, fixed paddings\")\n\ndiv = Divider(fig, rect, horiz, vert, aspect=False)\n\n# The rect parameter will actually be ignored and overridden by axes_locator.\nax1 = fig.add_axes(rect, axes_locator=div.new_locator(nx=0, ny=0))\nlabel_axes(ax1, \"nx=0, ny=0\")\nax2 = fig.add_axes(rect, axes_locator=div.new_locator(nx=0, ny=2))\nlabel_axes(ax2, \"nx=0, ny=2\")\nax3 = fig.add_axes(rect, axes_locator=div.new_locator(nx=2, ny=2))\nlabel_axes(ax3, \"nx=2, ny=2\")\nax4 = fig.add_axes(rect, axes_locator=div.new_locator(nx=2, nx1=4, ny=0))\nlabel_axes(ax4, \"nx=2, nx1=4, ny=0\")\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Sizes are in inches.\nhoriz = [Size.Scaled(1.5), Size.Fixed(.5), Size.Scaled(1.), Size.Scaled(.5)]\nvert = [Size.Scaled(1.), Size.Fixed(.5), Size.Scaled(1.5)]\n\nrect = (0.1, 0.1, 0.8, 0.8)\nfig = plt.figure(figsize=(6, 6))\nfig.suptitle(\"Scalable axes sizes, fixed paddings\")\n\ndiv = Divider(fig, rect, horiz, vert, aspect=False)\n\n# The rect parameter will actually be ignored and overridden by axes_locator.\nax1 = fig.add_axes(rect, axes_locator=div.new_locator(nx=0, ny=0))\nlabel_axes(ax1, \"nx=0, ny=0\")\nax2 = fig.add_axes(rect, axes_locator=div.new_locator(nx=0, ny=2))\nlabel_axes(ax2, \"nx=0, ny=2\")\nax3 = fig.add_axes(rect, axes_locator=div.new_locator(nx=2, ny=2))\nlabel_axes(ax3, \"nx=2, ny=2\")\nax4 = fig.add_axes(rect, axes_locator=div.new_locator(nx=2, nx1=4, ny=0))\nlabel_axes(ax4, \"nx=2, nx1=4, ny=0\")\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-axes-divider":{"intro":"In this lab, we will learn how to use the Matplotlib Axes Divider to create custom layouts for subplots in a figure.","steps":[{"title":"Import necessary libraries","body":["We will start by importing the necessary libraries for this lab: matplotlib.pyplot and mpl_toolkits.axes_grid1."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.axes_grid1 import Divider\nimport mpl_toolkits.axes_grid1.axes_size as Size"}]},{"title":"Set up the figure and axes","body":["We will create a figure object and set up four axes objects using the fig.add_axes method."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(5.5, 4))\nrect = (0.1, 0.1, 0.8, 0.8)\nax = [fig.add_axes(rect, label=\"%d\" % i) for i in range(4)]"}]},{"title":"Set up the axes divider","body":["We will set up the axes divider using the Divider class and AxesX and AxesY classes from the mpl_toolkits.axes_grid1.axes_size module. Then, we will use the new_locator method to set the position of each axis."],"code":[{"lang":"python","text":"horiz = [Size.AxesX(ax[0]), Size.Fixed(.5), Size.AxesX(ax[1])]\nvert = [Size.AxesY(ax[0]), Size.Fixed(.5), Size.AxesY(ax[2])]\ndivider = Divider(fig, rect, horiz, vert, aspect=False)\n\nax[0].set_axes_locator(divider.new_locator(nx=0, ny=0))\nax[1].set_axes_locator(divider.new_locator(nx=2, ny=0))\nax[2].set_axes_locator(divider.new_locator(nx=0, ny=2))\nax[3].set_axes_locator(divider.new_locator(nx=2, ny=2))"}]},{"title":"Customize the axes limits and appearance","body":["Customize the axes limits and appearance","We will customize the limits and appearance of each axis using the set_xlim, set_ylim, and tick_params methods."],"code":[{"lang":"python","text":"ax[0].set_xlim(0, 2)\nax[1].set_xlim(0, 1)\nax[0].set_ylim(0, 1)\nax[2].set_ylim(0, 2)\nfor ax1 in ax:\n    ax1.tick_params(labelbottom=False, labelleft=False)"}]},{"title":"Display the plot","body":["Finally, we will display the plot using the show method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-image-grid-alignment-in-matplotlib":{"intro":"In this tutorial, we will learn how to use the ImageGrid function from the mpl_toolkits.axes_grid1 module in Matplotlib. We will create a 2x2 grid of images and align them using the ImageGrid function.","steps":[{"title":"Import necessary libraries and create image arrays","body":["Import necessary libraries and create image arrays","We begin by importing the necessary libraries and creating four 10x10 image arrays using the arange and reshape functions from the NumPy library."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom mpl_toolkits.axes_grid1 import ImageGrid\n\nim1 = np.arange(100).reshape((10, 10))\nim2 = im1.T\nim3 = np.flipud(im1)\nim4 = np.fliplr(im2)"}]},{"title":"Create a figure and an ImageGrid object","body":["Create a figure and an ImageGrid object","Next, we create a figure object using the plt.figure function and pass in the figsize argument to set the size of the figure. We then create an ImageGrid object using the ImageGrid function and pass in the figure, 111 as the subplot argument, (2, 2) as the nrows_ncols argument to create a 2x2 grid of axes, and 0.1 as the axes_pad argument to set the padding between the axes."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(4., 4.))\ngrid = ImageGrid(fig, 111, nrows_ncols=(2, 2), axes_pad=0.1)"}]},{"title":"Iterate over the grid and plot the images","body":["Iterate over the grid and plot the images","We then iterate over the grid object using the zip function to iterate over both the axes and the image arrays. We plot each image on its corresponding axis using the imshow function."],"code":[{"lang":"python","text":"for ax, im in zip(grid, [im1, im2, im3, im4]):\n    ax.imshow(im)"}]},{"title":"Show the plot","body":["Finally, we show the plot using the plt.show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-align-images-using-matplotlib-s-imagegrid":{"intro":"In this tutorial, we will learn how to use ImageGrid from mpl_toolkits.axes_grid1 in Matplotlib to align multiple images of different sizes.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","First, we need to import the necessary libraries including Matplotlib, cbook and ImageGrid."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib import cbook\nfrom mpl_toolkits.axes_grid1 import ImageGrid"}]},{"title":"Create a Figure and ImageGrid","body":["Next, we create a figure and ImageGrid with nrows_ncols parameter to define the number of rows and columns of the grid."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(5.5, 3.5))\ngrid = ImageGrid(fig, 111,  # similar to subplot(111)\n                 nrows_ncols=(1, 3),\n                 axes_pad=0.1,\n                 label_mode=\"L\")"}]},{"title":"Load the image data","body":["We will use an example image data called bivariate_normal.npy from cbook to demonstrate the ImageGrid. We load the image data using get_sample_data function from cbook."],"code":[{"lang":"python","text":"Z = cbook.get_sample_data(\"axes_grid/bivariate_normal.npy\")\nim1 = Z\nim2 = Z[:, :10]\nim3 = Z[:, 10:]\nvmin, vmax = Z.min(), Z.max()"}]},{"title":"Display images in the ImageGrid","body":["Display images in the ImageGrid","Finally, we display the images in the ImageGrid using imshow function and zip function to iterate through the axes in the grid."],"code":[{"lang":"python","text":"for ax, im in zip(grid, [im1, im2, im3]):\n    ax.imshow(im, origin=\"lower\", vmin=vmin, vmax=vmax)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"for ax, im in zip(grid, [im1, im2, im3]):\n    ax.imshow(im, origin=\"lower\", vmin=vmin, vmax=vmax)\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-simple-axis-direction":{"intro":"In this step-by-step lab, we will be learning how to create a simple axis direction in Python Matplotlib. Matplotlib is a data visualization library in Python that allows you to create static, animated, and interactive visualizations in Python programming. We will be using the library to create a simple axis direction diagram using the following steps.","steps":[{"title":"Import Libraries","body":["First, we import the necessary libraries. In this case, we will be importing matplotlib.pyplot and mpl_toolkits.axisartist."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport mpl_toolkits.axisartist as axisartist"}]},{"title":"Create the Figure and Axes","body":["Next, we create the figure and axes objects using the plt.subplots() function. We specify the figure size using the figsize parameter."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(4, 2.5))\nax1 = fig.add_subplot(axes_class=axisartist.Axes)"}]},{"title":"Adjust the Subplot","body":["We adjust the subplot using the fig.subplots_adjust() function to make room for the labels on the right side of the plot."],"code":[{"lang":"python","text":"fig.subplots_adjust(right=0.8)"}]},{"title":"Set the Axis Labels","body":["We set the axis labels for the left and right sides of the plot using the ax1.axis[] function. We also set the direction of the tick labels using the set_axis_direction() function."],"code":[{"lang":"python","text":"ax1.axis[\"left\"].major_ticklabels.set_axis_direction(\"top\")\nax1.axis[\"left\"].label.set_text(\"Left label\")\n\nax1.axis[\"right\"].label.set_visible(True)\nax1.axis[\"right\"].label.set_text(\"Right label\")\nax1.axis[\"right\"].label.set_axis_direction(\"left\")"}]},{"title":"Show the Plot","body":["Finally, we show the plot using the plt.show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-simple-axis-tickel-and-tick-directions":{"intro":"This lab will guide you on how to create simple axis tick labels and tick directions using Matplotlib. The code will help you move the tick labels and ticks to inside the spines.","steps":[{"title":"Import Libraries","body":["Import the necessary libraries to create the plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport mpl_toolkits.axisartist as axisartist"}]},{"title":"Setup Axes Function","body":["Create a function to set up the axes. This function will set the x and y tick values."],"code":[{"lang":"python","text":"def setup_axes(fig, pos):\n    ax = fig.add_subplot(pos, axes_class=axisartist.Axes)\n    ax.set_yticks([0.2, 0.8])\n    ax.set_xticks([0.2, 0.8])\n    return ax"}]},{"title":"Create the Figure and Subplots","body":["Create the Figure and Subplots","Create the figure and two subplots using the setup_axes() function."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(5, 2))\nfig.subplots_adjust(wspace=0.4, bottom=0.3)\n\nax1 = setup_axes(fig, 121)\nax1.set_xlabel(\"ax1 X-label\")\nax1.set_ylabel(\"ax1 Y-label\")\n\nax2 = setup_axes(fig, 122)\nax2.set_xlabel(\"ax2 X-label\")\nax2.set_ylabel(\"ax2 Y-label\")"}]},{"title":"Move Tick Labels Inside the Spines","body":["Move Tick Labels Inside the Spines","Move the tick labels to inside the spines for the first subplot using the invert_ticklabel_direction() method."],"code":[{"lang":"python","text":"ax1.axis[:].invert_ticklabel_direction()"}]},{"title":"Move Ticks Inside the Spines","body":["Move the ticks to inside the spines for the second subplot using the major_ticks.set_tick_out() method."],"code":[{"lang":"python","text":"ax2.axis[:].major_ticks.set_tick_out(False)"}]},{"title":"Display the Plot","body":["Display the plot using the show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-simple-axis-pad":{"intro":"This lab will teach you how to use the add_floating_axis function in Matplotlib to add floating axes to a plot, which can be used to display additional information about the plot. Specifically, you will learn how to adjust the padding of tick labels and axis labels, as well as how to adjust the position of ticks on the floating axes.","steps":[{"title":"Import Libraries","body":["First, import the necessary libraries, including matplotlib.pyplot, numpy, and mpl_toolkits.axisartist."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport mpl_toolkits.axisartist as axisartist"}]},{"title":"Define Setup Axes Function","body":["Next, define the setup_axes() function, which sets up the polar projection of the plot. This function uses a GridHelperCurveLinear to create a polar projection in a rectangular box. It also sets the limits of the plot and returns the ax1 object."],"code":[{"lang":"python","text":"def setup_axes(fig, rect):\n    # Define the PolarAxes transform and the extreme finder\n    tr = Affine2D().scale(np.pi/180., 1.) + PolarAxes.PolarTransform()\n    extreme_finder = angle_helper.ExtremeFinderCycle(20, 20, lon_cycle=360, lat_cycle=None, lon_minmax=None, lat_minmax=(0, np.inf))\n\n    # Define the grid locators and formatters\n    grid_locator1 = angle_helper.LocatorDMS(12)\n    grid_locator2 = grid_finder.MaxNLocator(5)\n    tick_formatter1 = angle_helper.FormatterDMS()\n\n    # Define the GridHelperCurveLinear\n    grid_helper = GridHelperCurveLinear(tr, extreme_finder=extreme_finder, grid_locator1=grid_locator1, grid_locator2=grid_locator2, tick_formatter1=tick_formatter1)\n\n    # Create the axis object and set its limits\n    ax1 = fig.add_subplot(rect, axes_class=axisartist.Axes, grid_helper=grid_helper)\n    ax1.axis[:].set_visible(False)\n    ax1.set_aspect(1.)\n    ax1.set_xlim(-5, 12)\n    ax1.set_ylim(-5, 10)\n\n    return ax1"}]},{"title":"Define Add Floating Axis Function","body":["Define Add Floating Axis Function","Define the add_floating_axis function, which adds a floating axis to the plot. This function takes in the ax1 object as an argument and returns the axis object."],"code":[{"lang":"python","text":"def add_floating_axis(ax1):\n    # Define the floating axis\n    ax1.axis[\"lat\"] = axis = ax1.new_floating_axis(0, 30)\n    axis.label.set_text(r\"$\\theta = 30^{\\circ}$\")\n    axis.label.set_visible(True)\n\n    return axis"}]},{"title":"Add Padding to Tick Labels","body":["In this step, add padding to the tick labels on the floating axis. This can be done by setting the pad attribute of the major_ticklabels object to the desired padding value."],"code":[{"lang":"python","text":"# Add Padding to Tick Labels\nfig = plt.figure(figsize=(9, 3.))\nfig.subplots_adjust(left=0.01, right=0.99, bottom=0.01, top=0.99, wspace=0.01, hspace=0.01)\n\nax1 = setup_axes(fig, rect=121)\naxis = add_floating_axis(ax1)\n\nax1 = setup_axes(fig, rect=122)\naxis = add_floating_axis(ax1)\naxis.major_ticklabels.set_pad(10)\n\nplt.show()"}]},{"title":"Adjust Axis Label Padding","body":["In this step, adjust the padding of the axis label on the floating axis. This can be done by setting the pad attribute of the label object to the desired padding value."],"code":[{"lang":"python","text":"# Adjust Axis Label Padding\nfig = plt.figure(figsize=(9, 3.))\nfig.subplots_adjust(left=0.01, right=0.99, bottom=0.01, top=0.99, wspace=0.01, hspace=0.01)\n\nax1 = setup_axes(fig, rect=121)\naxis = add_floating_axis(ax1)\n\nax1 = setup_axes(fig, rect=122)\naxis = add_floating_axis(ax1)\naxis.label.set_pad(20)\n\nplt.show()"}]},{"title":"Adjust Tick Position","body":["In this step, adjust the position of the ticks on the floating axis. This can be done by setting the tick_out attribute of the major_ticks object to True."],"code":[{"lang":"python","text":"# Adjust Tick Position\nfig = plt.figure(figsize=(9, 3.))\nfig.subplots_adjust(left=0.01, right=0.99, bottom=0.01, top=0.99, wspace=0.01, hspace=0.01)\n\nax1 = setup_axes(fig, rect=121)\naxis = add_floating_axis(ax1)\n\nax1 = setup_axes(fig, rect=122)\naxis = add_floating_axis(ax1)\naxis.major_ticks.set_tick_out(True)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Adjust Tick Position\nfig = plt.figure(figsize=(9, 3.))\nfig.subplots_adjust(left=0.01, right=0.99, bottom=0.01, top=0.99, wspace=0.01, hspace=0.01)\n\nax1 = setup_axes(fig, rect=121)\naxis = add_floating_axis(ax1)\n\nax1 = setup_axes(fig, rect=122)\naxis = add_floating_axis(ax1)\naxis.major_ticks.set_tick_out(True)\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-custom-spines-with-axisartist":{"intro":"This tutorial will show you how to use the Matplotlib library to create custom spines at specific positions.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries for this tutorial. We will be using Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom mpl_toolkits import axisartist"}]},{"title":"Create Figure and Subplots","body":["We will create a figure with two subplots using the add_gridspec method."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(6, 3), layout=\"constrained\")\ngs = fig.add_gridspec(1, 2)"}]},{"title":"Create Subplot 1","body":["In the first subplot, we will create a new axis that passes through y=0 using axisartist.Axes. We will also make the other spines invisible."],"code":[{"lang":"python","text":"ax0 = fig.add_subplot(gs[0, 0], axes_class=axisartist.Axes)\nax0.axis[\"y=0\"] = ax0.new_floating_axis(nth_coord=0, value=0, axis_direction=\"bottom\")\nax0.axis[\"y=0\"].toggle(all=True)\nax0.axis[\"y=0\"].label.set_text(\"y = 0\")\nax0.axis[\"bottom\", \"top\", \"right\"].set_visible(False)"}]},{"title":"Create Subplot 2","body":["In the second subplot, we will use axisartist.axislines.AxesZero to automatically create xzero and yzero axes. We will make the other spines invisible and set the xzero axis visible."],"code":[{"lang":"python","text":"ax1 = fig.add_subplot(gs[0, 1], axes_class=axisartist.axislines.AxesZero)\nax1.axis[\"xzero\"].set_visible(True)\nax1.axis[\"xzero\"].label.set_text(\"Axis Zero\")\nax1.axis[\"bottom\", \"top\", \"right\"].set_visible(False)"}]},{"title":"Plot Data","body":["Now that we have created our subplots, we can plot our data using np.sin(x)."],"code":[{"lang":"python","text":"x = np.arange(0, 2*np.pi, 0.01)\nax0.plot(x, np.sin(x))\nax1.plot(x, np.sin(x))"}]},{"title":"Show Plot","body":["Finally, we can display our plot using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-simple-matplotlib-axisline":{"intro":"In this lab, we will learn how to create a simple axis line using Matplotlib. We will use the mpl_toolkits.axisartist.axislines library to create an axis line with x and y axis labels, and a y2 axis label on the right side. We will also learn how to hide the top and right axes, and make the x axis line visible at y=0.","steps":[{"title":"Import Libraries","body":["We start by importing the necessary libraries. We will be using Matplotlib and the mpl_toolkits.axisartist.axislines library."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.axisartist.axislines import AxesZero"}]},{"title":"Create Figure and Subplot","body":["Next, we create a figure and add a subplot with AxesZero. This creates an axis line with x and y axis labels, but no tick marks or grids."],"code":[{"lang":"python","text":"fig = plt.figure()\nfig.subplots_adjust(right=0.85)\nax = fig.add_subplot(axes_class=AxesZero)"}]},{"title":"Hide Top and Right Axes","body":["We will now hide the top and right axes, since we only need the left and bottom axes."],"code":[{"lang":"python","text":"ax.axis[\"right\"].set_visible(False)\nax.axis[\"top\"].set_visible(False)"}]},{"title":"Make X Axis Line Visible at Y=0","body":["Make X Axis Line Visible at Y=0","We will now make the x axis line visible at y=0. This is done by setting the xzero axis to visible."],"code":[{"lang":"python","text":"ax.axis[\"xzero\"].set_visible(True)\nax.axis[\"xzero\"].label.set_text(\"Axis Zero\")"}]},{"title":"Set Axis Limits and Labels","body":["We will now set the y axis limits to (-2, 4) and set the x and y axis labels."],"code":[{"lang":"python","text":"ax.set_ylim(-2, 4)\nax.set_xlabel(\"Label X\")\nax.set_ylabel(\"Label Y\")"}]},{"title":"Create Y2 Axis","body":["Finally, we will create a new y2 axis on the right side of the plot with an offset of (20, 0) and label it."],"code":[{"lang":"python","text":"ax.axis[\"right2\"] = ax.new_fixed_axis(loc=\"right\", offset=(20, 0))\nax.axis[\"right2\"].label.set_text(\"Label Y2\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax.axis[\"right2\"] = ax.new_fixed_axis(loc=\"right\", offset=(20, 0))\nax.axis[\"right2\"].label.set_text(\"Label Y2\")"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-simple-axisline3":{"intro":"In this tutorial, we will learn how to create a simple axis line using Matplotlib in Python.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.axisartist.axislines import Axes"}]},{"title":"Create Figure and Axes","body":["Next, we will create a figure and axes object. We will use the add_subplot method to add the axes object."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(3, 3))\nax = fig.add_subplot(axes_class=Axes)"}]},{"title":"Customize the Axes","body":["We will now customize the axes by hiding the right and top axes lines."],"code":[{"lang":"python","text":"ax.axis[\"right\"].set_visible(False)\nax.axis[\"top\"].set_visible(False)"}]},{"title":"Display the Plot","body":["Finally, we can display the plot using the show method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-dual-axis-matplotlib-plot":{"intro":"This tutorial will guide you through the steps of creating a simple plot using Matplotlib, a Python library used for data visualization. We will be using the host_subplot module to create a plot with two y-axes.","steps":[{"title":"Import necessary modules","body":["The first step is to import the necessary modules for our plot. We will be using numpy to generate our x and y data, matplotlib.pyplot to create the plot, and mpl_toolkits.axes_grid1 to create the second y-axis."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom mpl_toolkits.axes_grid1 import host_subplot"}]},{"title":"Generate data","body":["Next, we need to generate our x and y data. We will be generating a sine wave for this example."],"code":[{"lang":"python","text":"xx = np.arange(0, 2*np.pi, 0.01)\nyy = np.sin(xx)"}]},{"title":"Create the plot","body":["Now we can create our plot using the host_subplot function. This function creates a subplot with two y-axes."],"code":[{"lang":"python","text":"ax = host_subplot(111)\nax.plot(xx, yy)"}]},{"title":"Create the second y-axis","body":["To create the second y-axis, we need to create a new axis object using the twin function."],"code":[{"lang":"python","text":"ax2 = ax.twin()"}]},{"title":"Set tick labels for the second y-axis","body":["Set tick labels for the second y-axis","We can set the tick labels for the second y-axis using the set_xticks function and passing in the tick locations and labels as arguments."],"code":[{"lang":"python","text":"ax2.set_xticks([0., .5*np.pi, np.pi, 1.5*np.pi, 2*np.pi],\n               labels=[\"$0$\", r\"$\\frac{1}{2}\\pi$\",\n                       r\"$\\pi$\", r\"$\\frac{3}{2}\\pi$\", r\"$2\\pi$\"])"}]},{"title":"Hide tick labels for the right y-axis","body":["Hide tick labels for the right y-axis","We can hide the tick labels for the right y-axis using the major_ticklabels.set_visible function."],"code":[{"lang":"python","text":"ax2.axis[\"right\"].major_ticklabels.set_visible(False)"}]},{"title":"Show tick labels for the top y-axis","body":["Show tick labels for the top y-axis","We can show the tick labels for the top y-axis using the same major_ticklabels.set_visible function."],"code":[{"lang":"python","text":"ax2.axis[\"top\"].major_ticklabels.set_visible(True)"}]},{"title":"Display the plot","body":["Finally, we can display our plot using the show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-simple-colorbar":{"intro":"In this lab, we will learn how to add a simple colorbar to a Matplotlib plot. A colorbar is a useful tool for visualizing the range of values represented by colors in a plot. We will use the imshow function to create a simple 2D plot and then add a colorbar to it.","steps":[{"title":"Import libraries","body":["To get started, we need to import the necessary libraries. We will use the numpy and matplotlib.pyplot libraries for this lab."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a 2D plot","body":["Next, we will create a simple 2D plot using the imshow function."],"code":[{"lang":"python","text":"# Create a 2D array\ndata = np.random.rand(10, 10)\n\n# Plot the array\nplt.imshow(data)"}]},{"title":"Add a colorbar","body":["Now we can add a colorbar to the plot using the colorbar function."],"code":[{"lang":"python","text":"# Add a colorbar to the plot\nplt.colorbar()"}]},{"title":"Customize the colorbar","body":["We can customize the appearance of the colorbar by using the cmap parameter. This parameter specifies the color map used to create the plot."],"code":[{"lang":"python","text":"# Customize the colorbar\nplt.colorbar(cmap='viridis')"}]},{"title":"Add a label to the colorbar","body":["We can add a label to the colorbar using the label parameter."],"code":[{"lang":"python","text":"# Add a label to the colorbar\nplt.colorbar(cmap='viridis', label='Random Data')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Add a label to the colorbar\nplt.colorbar(cmap='viridis', label='Random Data')"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-matplotlib-plot-legends":{"intro":"Matplotlib is a Python library that enables users to create various types of graphs and plots. This tutorial will guide you through the process of creating a legend in a Matplotlib plot.","steps":[{"title":"Import necessary libraries","body":["Before we start, we need to import the necessary libraries. In this case, we will be using the Matplotlib library."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Create a figure and subplot","body":["We need to create a figure and subplot to plot our data. We will be creating a plot with two subplots."],"code":[{"lang":"python","text":"fig = plt.figure()\n\nax = fig.add_subplot(211)\nax.plot([1, 2, 3], label=\"test1\")\nax.plot([3, 2, 1], label=\"test2\")\n\nax = fig.add_subplot(223)\nax.plot([1, 2, 3], label=\"test1\")\nax.plot([3, 2, 1], label=\"test2\")"}]},{"title":"Add a legend to the plot","body":["We will now add a legend to the plot. There are two ways to add a legend in Matplotlib. We will use both methods in this example."],"code":[{"lang":"python","text":"# Method 1: Place a legend above the subplot\nax.legend(bbox_to_anchor=(0., 1.02, 1., .102), loc='lower left',\n           ncols=2, mode=\"expand\", borderaxespad=0.)\n\n# Method 2: Place a legend to the right of the subplot\nax.legend(bbox_to_anchor=(1.05, 1), loc='upper left', borderaxespad=0.)"}]},{"title":"Display the plot","body":["Finally, we will display the plot."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-legend-creation-tutorial":{"intro":"Matplotlib is a plotting library for the Python programming language and its numerical mathematics extension NumPy. In this tutorial, we will learn how to create a simple legend with Matplotlib.","steps":[{"title":"Import Matplotlib","body":["To use Matplotlib, we need to import it first."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Create a Figure and Axes","body":["We need to create a figure and axes to plot our data."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"}]},{"title":"Plot the Data","body":["We can plot our data using the plot() function."],"code":[{"lang":"python","text":"line1, = ax.plot([1, 2, 3], label=\"Line 1\", linestyle='--')\nline2, = ax.plot([3, 2, 1], label=\"Line 2\", linewidth=4)"}]},{"title":"Create the First Legend","body":["We can create a legend for the first line using the legend() function."],"code":[{"lang":"python","text":"first_legend = ax.legend(handles=[line1], loc='upper right')"}]},{"title":"Add the First Legend","body":["We need to add the first legend to the plot using the add_artist() function."],"code":[{"lang":"python","text":"ax.add_artist(first_legend)"}]},{"title":"Create the Second Legend","body":["We can create another legend for the second line using the legend() function."],"code":[{"lang":"python","text":"ax.legend(handles=[line2], loc='lower right')"}]},{"title":"Show the Plot","body":["We can show the plot using the show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-visualization-tutorial":{"intro":"This tutorial will guide you through creating a simple plot using Python's Matplotlib library. Matplotlib is a data visualization library widely used in scientific computing to create static, animated, and interactive visualizations in Python.","steps":[{"title":"Import necessary libraries","body":["Before we start creating the plot, we need to import the necessary libraries. In this case, we need to import numpy and matplotlib.pyplot."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt"}]},{"title":"Generate Data","body":["We need to generate data for the plot. In this example, we will generate two arrays, t and s."],"code":[{"lang":"python","text":"t = np.arange(0.0, 2.0, 0.01)\ns = 1 + np.sin(2 * np.pi * t)"}]},{"title":"Create the plot","body":["Now that we have the data, we can create the plot. First, we create a figure and axis object using plt.subplots(). Then, we plot the data using ax.plot()."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.plot(t, s)"}]},{"title":"Add labels and title","body":["We can add labels to the x and y axis, as well as a title to the plot using ax.set()."],"code":[{"lang":"python","text":"ax.set(xlabel='time (s)', ylabel='voltage (mV)', title='About as simple as it gets, folks')"}]},{"title":"Add a grid","body":["Finally, we can add a grid to the plot using ax.grid()."],"code":[{"lang":"python","text":"ax.grid()"}]},{"title":"Show the plot","body":["We can use plt.show() to display the plot."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-animated-scatter-plot":{"intro":"This lab is designed to teach you how to create an animated scatter plot using Python's Matplotlib library. We will cover everything from setting up the plot to saving the animation as a GIF. By the end of this lab, you will have a working animated scatter plot that you can use to visualize your data.","steps":[{"title":"Setting up the Plot","body":["The first step in creating an animated scatter plot is to set up the plot itself. This involves importing the necessary libraries and creating a figure and axes object."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfig, ax = plt.subplots()"}]},{"title":"Defining the Data","body":["Next, we need to define the data that we will be using for our scatter plot. In this example, we will be using a simple array of numbers ranging from 0 to 10."],"code":[{"lang":"python","text":"x = np.linspace(0, 10)"}]},{"title":"Creating the Scatter Plot","body":["Now that we have our data, we can create the scatter plot. We do this by calling the scatter function on our axes object and passing in our x data."],"code":[{"lang":"python","text":"scat = ax.scatter(1, 0)"}]},{"title":"Creating the Animation","body":["The final step is to create the animation. We do this using the FuncAnimation function from the animation module. This function takes a few arguments, including the figure object, the function that will update the plot, and the number of frames to use."],"code":[{"lang":"python","text":"def animate(i):\n    scat.set_offsets((x[i], 0))\n    return scat,\n\nani = animation.FuncAnimation(fig, animate, repeat=True,\n                                    frames=len(x) - 1, interval=50)"}]},{"title":"Displaying the Plot","body":["We can now display the plot by calling the show function from the pyplot module."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-skewt-logp-diagram-using-matplotlib":{"intro":"In this lab, we will learn how to create a SkewT-logP diagram using Matplotlib library in Python. A SkewT-logP diagram is commonly used in meteorology for displaying vertical profiles of temperature. It is a complex plot as it involves non-orthogonal X and Y axes. We will use the Matplotlib's transforms and custom projection API to create this plot.","steps":[{"title":"Import Required Libraries","body":["We will start by importing the required libraries. We will be using Matplotlib, NumPy and StringIO for this example."],"code":[{"lang":"python","text":"from contextlib import ExitStack\nfrom matplotlib.axes import Axes\nimport matplotlib.axis as maxis\nfrom matplotlib.projections import register_projection\nimport matplotlib.spines as mspines\nimport matplotlib.transforms as transforms\nimport matplotlib.pyplot as plt\nimport numpy as np\nfrom io import StringIO\nfrom matplotlib.ticker import (MultipleLocator, NullFormatter, ScalarFormatter)"}]},{"title":"Define SkewXTick Class","body":["The SkewXTick class is used to draw the ticks on the SkewT-logP diagram. It checks if the tick needs to be drawn on the upper or lower X-axis and accordingly sets the visibility of the tick and gridline."],"code":[{"lang":"python","text":"class SkewXTick(maxis.XTick):\n    def draw(self, renderer):\n        with ExitStack() as stack:\n            for artist in [self.gridline, self.tick1line, self.tick2line, self.label1, self.label2]:\n                stack.callback(artist.set_visible, artist.get_visible())\n            needs_lower = transforms.interval_contains(self.axes.lower_xlim, self.get_loc())\n            needs_upper = transforms.interval_contains(self.axes.upper_xlim, self.get_loc())\n            self.tick1line.set_visible(self.tick1line.get_visible() and needs_lower)\n            self.label1.set_visible(self.label1.get_visible() and needs_lower)\n            self.tick2line.set_visible(self.tick2line.get_visible() and needs_upper)\n            self.label2.set_visible(self.label2.get_visible() and needs_upper)\n            super().draw(renderer)\n\n    def get_view_interval(self):\n        return self.axes.xaxis.get_view_interval()"}]},{"title":"Define SkewXAxis Class","body":["The SkewXAxis class is used to provide two separate sets of intervals to the tick and create instances of the custom tick."],"code":[{"lang":"python","text":"class SkewXAxis(maxis.XAxis):\n    def _get_tick(self, major):\n        return SkewXTick(self.axes, None, major=major)\n\n    def get_view_interval(self):\n        return self.axes.upper_xlim[0], self.axes.lower_xlim[1]"}]},{"title":"Define SkewSpine Class","body":["The SkewSpine class calculates the separate data range of the upper X-axis and draws the spine there. It also provides this range to the X-axis artist for ticking and gridlines."],"code":[{"lang":"python","text":"class SkewSpine(mspines.Spine):\n    def _adjust_location(self):\n        pts = self._path.vertices\n        if self.spine_type == 'top':\n            pts[:, 0] = self.axes.upper_xlim\n        else:\n            pts[:, 0] = self.axes.lower_xlim"}]},{"title":"Define SkewXAxes Class","body":["The SkewXAxes class handles the registration of the skew-xaxes as a projection as well as setting up the appropriate transformations. It overrides standard spines and axes instances as appropriate."],"code":[{"lang":"python","text":"class SkewXAxes(Axes):\n    name = 'skewx'\n\n    def _init_axis(self):\n        super()._init_axis()\n        self.xaxis = SkewXAxis(self)\n        self.spines.top.register_axis(self.xaxis)\n        self.spines.bottom.register_axis(self.xaxis)\n\n    def _gen_axes_spines(self):\n        spines = {'top': SkewSpine.linear_spine(self, 'top'),\n                  'bottom': mspines.Spine.linear_spine(self, 'bottom'),\n                  'left': mspines.Spine.linear_spine(self, 'left'),\n                  'right': mspines.Spine.linear_spine(self, 'right')}\n        return spines\n\n    def _set_lim_and_transforms(self):\n        super()._set_lim_and_transforms()\n        rot = 30\n        self.transDataToAxes = (self.transScale + self.transLimits + transforms.Affine2D().skew_deg(rot, 0))\n        self.transData = self.transDataToAxes + self.transAxes\n        self._xaxis_transform = (transforms.blended_transform_factory(\n            self.transScale + self.transLimits, transforms.IdentityTransform()) + transforms.Affine2D().skew_deg(rot, 0) + self.transAxes)\n\n    @property\n    def lower_xlim(self):\n        return self.axes.viewLim.intervalx\n\n    @property\n    def upper_xlim(self):\n        pts = [[0., 1.], [1., 1.]]\n        return self.transDataToAxes.inverted().transform(pts)[:, 0]"}]},{"title":"Register Projection","body":["We will register the projection with Matplotlib so that we can use it in our plot."],"code":[{"lang":"python","text":"register_projection(SkewXAxes)"}]},{"title":"Prepare Data","body":["We will prepare the data for our SkewT-logP diagram. We will use the StringIO module to read the data from a string and NumPy to load it into arrays."],"code":[{"lang":"python","text":"data_txt = '''\n        978.0    345    7.8    0.8\n        971.0    404    7.2    0.2\n        946.7    610    5.2   -1.8\n        ...\n    '''\nsound_data = StringIO(data_txt)\np, h, T, Td = np.loadtxt(sound_data, unpack=True)"}]},{"title":"Create SkewT-logP Diagram","body":["We will now create the SkewT-logP diagram using the SkewXAxes projection that we registered earlier. We will first create a figure object and add a subplot with the SkewXAxes projection. We will then plot the temperature and dew point data on the diagram using the semilogy function. Finally, we will set the limits and ticks for the X and Y axis and display the plot."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(6.5875, 6.2125))\nax = fig.add_subplot(projection='skewx')\n\nax.semilogy(T, p, color='C3')\nax.semilogy(Td, p, color='C2')\n\nax.axvline(0, color='C0')\n\nax.yaxis.set_major_formatter(ScalarFormatter())\nax.yaxis.set_minor_formatter(NullFormatter())\nax.set_yticks(np.linspace(100, 1000, 10))\nax.set_ylim(1050, 100)\n\nax.xaxis.set_major_locator(MultipleLocator(10))\nax.set_xlim(-50, 50)\n\nplt.grid(True)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig = plt.figure(figsize=(6.5875, 6.2125))\nax = fig.add_subplot(projection='skewx')\n\nax.semilogy(T, p, color='C3')\nax.semilogy(Td, p, color='C2')\n\nax.axvline(0, color='C0')\n\nax.yaxis.set_major_formatter(ScalarFormatter())\nax.yaxis.set_minor_formatter(NullFormatter())\nax.set_yticks(np.linspace(100, 1000, 10))\nax.set_ylim(1050, 100)\n\nax.xaxis.set_major_locator(MultipleLocator(10))\nax.set_xlim(-50, 50)\n\nplt.grid(True)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-sine-wave-sliders-with-matplotlib":{"intro":"In this tutorial, we will learn how to create sliders and use them to control a sine wave's frequency and amplitude. We will use the Matplotlib library to create a graph of the sine wave and the sliders. The sliders will allow us to adjust the frequency and amplitude of the sine wave.","steps":[{"title":"Import Libraries","body":["The first step is to import the necessary libraries. We will be using Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.widgets import Button, Slider"}]},{"title":"Define the Sine Wave Function","body":["Next, we will define the function that will generate our sine wave. The function will take in two parameters, amplitude and frequency, and return the sine wave at a given time."],"code":[{"lang":"python","text":"def f(t, amplitude, frequency):\n    return amplitude * np.sin(2 * np.pi * frequency * t)"}]},{"title":"Create the Initial Graph","body":["Now, we will create the initial graph of the sine wave. We will define the initial parameters for the amplitude and frequency and plot the sine wave using those parameters."],"code":[{"lang":"python","text":"t = np.linspace(0, 1, 1000)\ninit_amplitude = 5\ninit_frequency = 3\n\nfig, ax = plt.subplots()\nline, = ax.plot(t, f(t, init_amplitude, init_frequency), lw=2)\nax.set_xlabel('Time [s]')"}]},{"title":"Create the Sliders","body":["We will now create the sliders that will allow us to adjust the frequency and amplitude of the sine wave. We will create a horizontal slider to control the frequency and a vertical slider to control the amplitude."],"code":[{"lang":"python","text":"fig.subplots_adjust(left=0.25, bottom=0.25)\naxfreq = fig.add_axes([0.25, 0.1, 0.65, 0.03])\nfreq_slider = Slider(\n    ax=axfreq,\n    label='Frequency [Hz]',\n    valmin=0.1,\n    valmax=30,\n    valinit=init_frequency,\n)\n\naxamp = fig.add_axes([0.1, 0.25, 0.0225, 0.63])\namp_slider = Slider(\n    ax=axamp,\n    label=\"Amplitude\",\n    valmin=0,\n    valmax=10,\n    valinit=init_amplitude,\n    orientation=\"vertical\"\n)"}]},{"title":"Create the Update Function","body":["We will now create the function that will update the sine wave every time we adjust the sliders. The function will take in the values of the amplitude and frequency sliders, and update the sine wave accordingly."],"code":[{"lang":"python","text":"def update(val):\n    line.set_ydata(f(t, amp_slider.val, freq_slider.val))\n    fig.canvas.draw_idle()"}]},{"title":"Register the Update Function with the Sliders","body":["Register the Update Function with the Sliders","Next, we will register the update function with each slider so that the function is called every time we adjust the sliders."],"code":[{"lang":"python","text":"freq_slider.on_changed(update)\namp_slider.on_changed(update)"}]},{"title":"Create the Reset Button","body":["We will now create a reset button that will reset the sliders to their initial values."],"code":[{"lang":"python","text":"resetax = fig.add_axes([0.8, 0.025, 0.1, 0.04])\nbutton = Button(resetax, 'Reset', hovercolor='0.975')\n\ndef reset(event):\n    freq_slider.reset()\n    amp_slider.reset()\nbutton.on_clicked(reset)"}]},{"title":"Show the Graph","body":["Finally, we will show the graph with the sliders and the reset button."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-snapping-sliders":{"intro":"In this lab, you will learn how to use Matplotlib to create sliders with discrete values. You will learn how to constrain the values of a slider to a set of allowed values and snap the slider values to those allowed values.","steps":[{"title":"Import Required Libraries","body":["In this step, you will import the required libraries for this lab. You will be using Matplotlib to create the sliders and NumPy to generate the data to be plotted."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.widgets import Button, Slider"}]},{"title":"Generate Data","body":["In this step, you will generate the data to be plotted. You will create a sine wave with a frequency of 3 Hz and an amplitude of 5."],"code":[{"lang":"python","text":"t = np.arange(0.0, 1.0, 0.001)\na0 = 5\nf0 = 3\ns = a0 * np.sin(2 * np.pi * f0 * t)"}]},{"title":"Create the Figure and Axes","body":["In this step, you will create the figure and axes for the plot. You will also adjust the position of the axes to make room for the sliders."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nfig.subplots_adjust(bottom=0.25)\nl, = ax.plot(t, s, lw=2)\n\nax_freq = fig.add_axes([0.25, 0.1, 0.65, 0.03])\nax_amp = fig.add_axes([0.25, 0.15, 0.65, 0.03])"}]},{"title":"Define Allowed Values for the Amplitude Slider","body":["Define Allowed Values for the Amplitude Slider","In this step, you will define the allowed values for the amplitude slider. The amplitude slider will use these values to snap to the nearest allowed value."],"code":[{"lang":"python","text":"# define the values to use for snapping\nallowed_amplitudes = np.concatenate([np.linspace(.1, 5, 100), [6, 7, 8, 9]])"}]},{"title":"Create the Sliders","body":["In this step, you will create the sliders. You will create one slider for the amplitude and one slider for the frequency."],"code":[{"lang":"python","text":"samp = Slider(\n    ax_amp, \"Amp\", 0.1, 9.0,\n    valinit=a0, valstep=allowed_amplitudes,\n    color=\"green\"\n)\n\nsfreq = Slider(\n    ax_freq, \"Freq\", 0, 10*np.pi,\n    valinit=2*np.pi, valstep=np.pi,\n    initcolor='none'  # Remove the line marking the valinit position.\n)"}]},{"title":"Create the Update Function","body":["In this step, you will create the update function for the sliders. This function will update the plot when the slider values are changed."],"code":[{"lang":"python","text":"def update(val):\n    amp = samp.val\n    freq = sfreq.val\n    l.set_ydata(amp*np.sin(2*np.pi*freq*t))\n    fig.canvas.draw_idle()"}]},{"title":"Connect the Sliders to the Update Function","body":["Connect the Sliders to the Update Function","In this step, you will connect the sliders to the update function. This will ensure that the plot is updated whenever the slider values are changed."],"code":[{"lang":"python","text":"sfreq.on_changed(update)\nsamp.on_changed(update)"}]},{"title":"Create the Reset Button","body":[],"code":[{"lang":"python","text":"ax_reset = fig.add_axes([0.8, 0.025, 0.1, 0.04])\nbutton = Button(ax_reset, 'Reset', hovercolor='0.975')\n\ndef reset(event):\n    sfreq.reset()\n    samp.reset()\nbutton.on_clicked(reset)"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"}};
